1	// Saved-card / off-session charging primitives for subscription renewals.
2	//
3	// WHY THIS FILE EXISTS
4	// Until now a renewal could only debit the wallet (`worker/billing.ts` ->
5	// `debitWallet`). A customer with a perfectly good card on file was suspended the
6	// moment their wallet emptied, because `User.stripePaymentMethodId` was never
7	// written and never read. Everything needed to charge a card lives here; the
8	// worker owns the *policy* (when to retry, when to suspend), this module owns the
9	// *mechanics* (attach a card, charge it, credit the wallet for what it paid).
10	//
11	// THE MONEY MODEL — identical to checkout, deliberately
12	// Checkout applies wallet credit first and puts only the remainder on the card
13	// (`lib/wallet-split.ts`). Renewals now do the same: the card is charged the
14	// remainder, that exact amount is CREDITED to the wallet, and the existing
15	// CAS-guarded renewal transaction debits the FULL renewal from the wallet. So the
16	// wallet is always the thing that pays the bill and the card is always just a way
17	// to fund the wallet — one money path, already proven, and a partial failure can
18	// never half-apply a renewal.
19	//
20	// Plain server module (NOT "use server"): imported by the worker, by server
21	// actions and by server components. `lib/stripe.ts` is not modified by this file.
22	
23	import type Stripe from "stripe";
24	import { db } from "./db";
25	import { stripe, stripeConfigured } from "./stripe";
26	import { STRIPE_MIN_CENTS } from "./wallet-split";
27	import { invoiceCreateData } from "./invoices";
28	import { vpsTerm, vpsTermPriceCents } from "./billing-terms";
29	import { extraDiskCentsAt } from "./extra-disk";
30	
31	/* ------------------------------------------------------------------ *
32	 * Small shared helpers
33	 * ------------------------------------------------------------------ */
34	
35	function appBase(): string {
36	  return process.env.APP_URL ?? "http://localhost:3000";
37	}
38	
39	/** Audit actions used to decide whether an unclaimed Stripe card may be adopted. */
40	export const CARD_SETUP_STARTED = "card.setup_started";
41	export const CARD_REMOVED = "card.removed";
42	
43	/** How long a "I clicked Add card" intent stays good for the adoption backstop. */
44	const SETUP_INTENT_TTL_DAYS = 7;
45	
46	export type CardDisplay = {
47	  brand: string | null;
48	  last4: string | null;
49	  expMonth: number | null;
50	  expYear: number | null;
51	};
52	
53	/** "Visa ···· 4242, expires 04/28" — one formatter for UI, email and audit text. */
54	export function cardDisplayLabel(card: CardDisplay): string | null {
55	  if (!card.last4) return null;
56	  const brand = brandLabel(card.brand);
57	  const expiry =
58	    card.expMonth && card.expYear
59	      ? `, expires ${String(card.expMonth).padStart(2, "0")}/${String(card.expYear).slice(-2)}`
60	      : "";
61	  return `${brand} ···· ${card.last4}${expiry}`;
62	}
63	
64	/** Stripe brand ids are lowercase slugs ("visa", "amex", "unionpay"). */
65	export function brandLabel(brand: string | null | undefined): string {
66	  const map: Record<string, string> = {
67	    visa: "Visa",
68	    mastercard: "Mastercard",
69	    amex: "American Express",
70	    discover: "Discover",
71	    diners: "Diners Club",
72	    jcb: "JCB",
73	    unionpay: "UnionPay",
74	    cartes_bancaires: "Cartes Bancaires",
75	    eftpos_au: "Eftpos",
76	    link: "Link",
77	  };
78	  if (!brand) return "Card";
79	  return map[brand] ?? brand.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
80	}
81	
82	/**
83	 * A card is valid THROUGH the last day of its expiry month, so it stops working
84	 * at the first instant of the following month. Getting this off by a month would
85	 * either nag customers a month early or warn them after the renewal already failed.
86	 */
87	export function cardExpiresAt(expMonth: number, expYear: number): Date {
88	  return new Date(Date.UTC(expYear, expMonth, 1));
89	}
90	
91	/* ------------------------------------------------------------------ *
92	 * Renewal pricing — ONE formula, two callers
93	 * ------------------------------------------------------------------ */
94	
95	/**
96	 * What a renewal costs. Lives here (rather than being copied a third time)
97	 * because BOTH the worker sweep and the customer-facing "settle the balance"
98	 * link have to quote the same number — `renewNow` and the sweep already carry
99	 * the comment "the two renewal paths must never disagree", and a self-service
100	 * pay link that quotes a different total than the sweep charges is exactly how
101	 * that goes wrong.
102	 *
103	 * Pure: prices are passed in so the worker can read the admin settings once per
104	 * sweep instead of once per server.
105	 */
106	export type RenewalCharge = {
107	  months: number;
108	  totalCents: number;
109	  /** The extra-root-disk portion, which gets its own invoice line. */
110	  extraDiskCents: number;
111	  extraDiskMonthlyCents: number;
112	  /** Human label for the invoice / receipt ("Nebula VPS" or the game plan name). */
113	  label: string;
114	};
115	
116	export type PricedServer = {
117	  termMonths: number;
118	  extraDiskGB: number;
119	  plan: { name: string; priceCents: number };
120	  gamePlan: { name: string; priceCents: number; termMonths: number } | null;
121	  dedicatedIp: unknown | null;
122	};
123	
124	export function renewalCharge(
125	  server: PricedServer,
126	  prices: { ipMonthlyCents: number; extraDiskPerGbCents: number },
127	): RenewalCharge {
128	  const isGame = !!server.gamePlan;
129	  const months = isGame ? server.gamePlan!.termMonths : vpsTerm(server.termMonths).months;
130	  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
131	  // are a flat all-in price and never carry the add-on lines.
132	  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
133	  const extraDiskCents = extraDiskMonthlyCents * months;
134	  const totalCents = isGame
135	    ? server.gamePlan!.priceCents
136	    : vpsTermPriceCents(server.plan.priceCents, months) +
137	      // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP,
138	      // not off the intent flag — a NAT-fallback server must never be charged for
139	      // an IP it never received.
140	      (server.dedicatedIp ? prices.ipMonthlyCents * months : 0) +
141	      extraDiskCents;
142	  return {
143	    months,
144	    totalCents,
145	    extraDiskCents,
146	    extraDiskMonthlyCents,
147	    label: isGame ? server.gamePlan!.name : `${server.plan.name} VPS`,
148	  };
149	}
150	
151	/* ------------------------------------------------------------------ *
152	 * Stripe customer + saving a card
153	 * ------------------------------------------------------------------ */
154	
155	export type CardUser = {
156	  id: string;
157	  email: string;
158	  name?: string | null;
159	  stripeCustomerId: string | null;
160	  stripePaymentMethodId: string | null;
161	};
162	
163	/** True when this account can actually be charged off-session right now. */
164	export function hasChargeableCard(user: {
165	  stripeCustomerId: string | null;
166	  stripePaymentMethodId: string | null;
167	}): boolean {
168	  return stripeConfigured() && !!user.stripeCustomerId && !!user.stripePaymentMethodId;
169	}
170	
171	/**
172	 * Get-or-create the Stripe customer for an account and remember its id.
173	 *
174	 * `User.stripeCustomerId` has no UNIQUE constraint (the schema is frozen), so two
175	 * concurrent "Add card" clicks could otherwise mint two Stripe customers for one
176	 * person and strand the card on whichever one lost. The idempotency key — derived
177	 * only from our own user id — is what stops that: Stripe replays the first
178	 * customer instead of creating a second.
179	 */
180	export async function ensureStripeCustomer(user: CardUser): Promise<string> {
181	  if (user.stripeCustomerId) return user.stripeCustomerId;
182	  const fresh = await db.user.findUnique({
183	    where: { id: user.id },
184	    select: { stripeCustomerId: true },
185	  });
186	  if (fresh?.stripeCustomerId) return fresh.stripeCustomerId;
187	
188	  const customer = await stripe().customers.create(
189	    {
190	      email: user.email,
191	      name: user.name || undefined,
192	      metadata: { nxeonUserId: user.id },
193	    },
194	    { idempotencyKey: `nxeon_customer_${user.id}` },
195	  );
196	  await db.user.update({ where: { id: user.id }, data: { stripeCustomerId: customer.id } });
197	  return customer.id;
198	}
199	
200	/**
201	 * Hosted Checkout session in `mode: "setup"` — how a customer saves a card.
202	 *
203	 * Checkout rather than Stripe Elements because there is no Elements/Stripe.js
204	 * integration anywhere in this codebase and no publishable key plumbed to the
205	 * browser; a redirect to Stripe's own page reuses the exact flow that already
206	 * takes money for deploys, upgrades and top-ups.
207	 *
208	 * `usage: "off_session"` is load-bearing: it records a mandate that covers the
209	 * unattended renewal charges we make later. Without it many issuers (and every
210	 * SCA-regulated card) reject the first off-session charge outright, which would
211	 * turn "saved card" into "card that is declined once a month".
212	 */
213	export async function createCardSetupSession(
214	  user: CardUser,
215	  returnPath = "/dashboard/billing",
216	): Promise<string | null> {
217	  if (!stripeConfigured()) return null;
218	  const customerId = await ensureStripeCustomer(user);
219	  const base = appBase();
220	  const session = await stripe().checkout.sessions.create({
221	    mode: "setup",
222	    customer: customerId,
223	    payment_method_types: ["card"],
224	    setup_intent_data: { metadata: { nxeonUserId: user.id } },
225	    metadata: { nxeonUserId: user.id, nxeonCardSetup: "1" },
226	    // Deliberately NOT /api/stripe/confirm. A setup session has no amount and
227	    // `payment_status: "unpaid"`, so the shared fulfil path would classify it as a
228	    // wallet top-up and flash "Payment received — your balance updates within
229	    // seconds" at someone who only saved a card. We finalise through our own
230	    // server action instead.
231	    success_url: `${base}${returnPath}?card_setup={CHECKOUT_SESSION_ID}`,
232	    cancel_url: `${base}${returnPath}?card_setup=canceled`,
233	  });
234	  return session.url;
235	}
236	
237	/** Mirror the display fields + payment method for a card onto the account. */
238	async function persistCard(userId: string, customerId: string, pm: Stripe.PaymentMethod) {
239	  await db.user.update({
240	    where: { id: userId },
241	    data: {
242	      stripeCustomerId: customerId,
243	      stripePaymentMethodId: pm.id,
244	      cardBrand: pm.card?.brand ?? null,
245	      cardLast4: pm.card?.last4 ?? null,
246	      cardExpMonth: pm.card?.exp_month ?? null,
247	      cardExpYear: pm.card?.exp_year ?? null,
248	      // A brand-new card gets a fresh expiry-warning budget, otherwise a customer
249	      // who replaces an expiring card would never be warned about the new one.
250	      cardExpiryNotifiedAt: null,
251	    },
252	  });
253	}
254	
255	export type SavedCard = { brand: string | null; last4: string | null; expMonth: number | null; expYear: number | null };
256	
257	/**
258	 * Finalise a completed setup Checkout session: read the payment method off it,
259	 * make it the customer's default and mirror it onto the account.
260	 *
261	 * Verifies `metadata.nxeonUserId` against the caller. The session id travels in a
262	 * URL the customer can edit, so without that check a customer could paste someone
263	 * else's session id and attach their card to their own account.
264	 */
265	export async function saveCardFromSetupSession(
266	  sessionId: string,
267	  userId: string,
268	): Promise<{ card?: SavedCard; error?: string }> {
269	  if (!stripeConfigured()) return { error: "Card payments are not configured." };
270	  let session: Stripe.Checkout.Session;
271	  try {
272	    session = await stripe().checkout.sessions.retrieve(sessionId, { expand: ["setup_intent"] });
273	  } catch {
274	    return { error: "We couldn't read that card setup. Try adding the card again." };
275	  }
276	  if (session.mode !== "setup" || session.metadata?.nxeonUserId !== userId) {
277	    return { error: "That card setup doesn't belong to this account." };
278	  }
279	  if (session.status !== "complete") {
280	    return { error: "The card wasn't saved — the setup wasn't completed." };
281	  }
282	  const setupIntent = session.setup_intent as Stripe.SetupIntent | string | null;
283	  const pmRef =
284	    typeof setupIntent === "string" ? null : (setupIntent?.payment_method ?? null);
285	  const pmId = typeof pmRef === "string" ? pmRef : (pmRef?.id ?? null);
286	  const customerId =
287	    typeof session.customer === "string" ? session.customer : (session.customer?.id ?? null);
288	  if (!pmId || !customerId) return { error: "The card wasn't saved — no payment method came back." };
289	
290	  const pm = await stripe().paymentMethods.retrieve(pmId);
291	  // Checkout already attached the method to the customer; making it the default
292	  // means the adoption backstop below and anything Stripe-side pick the same card.
293	  await stripe()
294	    .customers.update(customerId, { invoice_settings: { default_payment_method: pmId } })
295	    .catch(() => {
296	      /* non-fatal: our own stripePaymentMethodId is the source of truth for charging */
297	    });
298	  await persistCard(userId, customerId, pm);
299	  return {
300	    card: {
301	      brand: pm.card?.brand ?? null,
302	      last4: pm.card?.last4 ?? null,
303	      expMonth: pm.card?.exp_month ?? null,
304	      expYear: pm.card?.exp_year ?? null,
305	    },
306	  };
307	}
308	
309	/**
310	 * Backstop for the closed-tab case.
311	 *
312	 * Checkout attaches the card to the Stripe customer BEFORE our `success_url` ever
313	 * runs. A customer who completes the Stripe page and then closes the tab has a
314	 * perfectly good card on file at Stripe and none on file here — and would be
315	 * dunned and suspended for it. This is the same class of bug as the Stripe
316	 * fulfilment incident: a browser redirect must never be the only trigger.
317	 *
318	 * Adoption is deliberately narrow. It requires a `card.setup_started` audit row
319	 * newer than any `card.removed` row and no older than a week, so a card the
320	 * customer explicitly REMOVED can never be silently resurrected and charged.
321	 */
322	export async function adoptUnclaimedCards(now = new Date()): Promise<number> {
323	  if (!stripeConfigured()) return 0;
324	  const since = new Date(now.getTime() - SETUP_INTENT_TTL_DAYS * 86400_000);
325	  const starts = await db.auditLog.findMany({
326	    where: { action: CARD_SETUP_STARTED, createdAt: { gt: since } },
327	    orderBy: { createdAt: "desc" },
328	    take: 200,
329	  });
330	  const userIds = [...new Set(starts.map((a) => a.userId).filter((v): v is string => !!v))];
331	  if (userIds.length === 0) return 0;
332	
333	  let adopted = 0;
334	  for (const userId of userIds) {
335	    const user = await db.user.findUnique({ where: { id: userId } });
336	    if (!user?.stripeCustomerId || user.stripePaymentMethodId) continue;
337	
338	    const startedAt = starts.find((a) => a.userId === userId)!.createdAt;
339	    const removed = await db.auditLog.findFirst({
340	      where: { userId, action: CARD_REMOVED },
341	      orderBy: { createdAt: "desc" },
342	    });
343	    if (removed && removed.createdAt > startedAt) continue; // removal is the later intent
344	
345	    try {
346	      const list = await stripe().paymentMethods.list({
347	        customer: user.stripeCustomerId,
348	        type: "card",
349	        limit: 5,
350	      });
351	      const pm = list.data[0]; // newest first
352	      if (!pm) continue;
353	      await persistCard(userId, user.stripeCustomerId, pm);
354	      await db.auditLog.create({
355	        data: {
356	          userId,
357	          action: "card.adopted",
358	          detail: `${cardDisplayLabel({
359	            brand: pm.card?.brand ?? null,
360	            last4: pm.card?.last4 ?? null,
361	            expMonth: pm.card?.exp_month ?? null,
362	            expYear: pm.card?.exp_year ?? null,
363	          })} (saved at Stripe but never confirmed in the browser)`,
364	        },
365	      });
366	      adopted++;
367	    } catch (e) {
368	      console.error(`[cards] could not adopt card for ${userId}`, e);
369	    }
370	  }
371	  return adopted;
372	}
373	
374	/**
375	 * Remove the saved card: detach at Stripe FIRST, and only clear our columns once
376	 * Stripe agrees the method is gone. Clearing locally while the method is still
377	 * attached would let `adoptUnclaimedCards` re-adopt it and charge a card the
378	 * customer had removed. A method that is already missing counts as removed.
379	 */
380	export async function detachSavedCard(userId: string): Promise<{ ok?: true; error?: string }> {
381	  const user = await db.user.findUnique({ where: { id: userId } });
382	  if (!user) return { error: "Account not found." };
383	  if (!user.stripePaymentMethodId) {
384	    await clearCardColumns(userId);
385	    return { ok: true };
386	  }
387	  if (stripeConfigured()) {
388	    try {
389	      await stripe().paymentMethods.detach(user.stripePaymentMethodId);
390	    } catch (e) {
391	      const err = asStripeError(e);
392	      if (err?.code !== "resource_missing") {
393	        console.error("[cards] detach failed", e);
394	        return { error: "We couldn't remove the card just now. Please try again in a moment." };
395	      }
396	    }
397	  }
398	  await clearCardColumns(userId);
399	  return { ok: true };
400	}
401	
402	async function clearCardColumns(userId: string) {
403	  await db.user.update({
404	    where: { id: userId },
405	    data: {
406	      stripePaymentMethodId: null,
407	      cardBrand: null,
408	      cardLast4: null,
409	      cardExpMonth: null,
410	      cardExpYear: null,
411	      cardExpiryNotifiedAt: null,
412	    },
413	  });
414	}
415	
416	/**
417	 * A customer who saves a card mid-dunning has been told (by
418	 * `emails.paymentFailed`) that we'll "charge it straight away". Bringing the
419	 * scheduled retry forward is what makes that copy true — the next sweep picks it
420	 * up instead of waiting for the day-3 or day-5 slot. The failure COUNT is left
421	 * alone: the money is still owed.
422	 */
423	export async function retryDunningNow(userId: string): Promise<number> {
424	  const res = await db.server.updateMany({
425	    where: { userId, dunningStage: { gt: 0 } },
426	    data: { dunningNextAt: new Date() },
427	  });
428	  return res.count;
429	}
430	
431	/* ------------------------------------------------------------------ *
432	 * Off-session charging
433	 * ------------------------------------------------------------------ */
434	
435	type StripeErrorLike = {
436	  type?: string;
437	  rawType?: string;
438	  code?: string;
439	  decline_code?: string;
440	  message?: string;
441	  payment_intent?: { id?: string; status?: string };
442	};
443	
444	function asStripeError(e: unknown): StripeErrorLike | null {
445	  if (!e || typeof e !== "object") return null;
446	  const err = e as StripeErrorLike;
447	  return err.rawType || err.type?.startsWith("Stripe") ? err : null;
448	}
449	
450	export type OffSessionResult =
451	  /** Money captured. `amountCents` is what Stripe actually took, not what we asked for. */
452	  | { ok: true; paymentIntentId: string; amountCents: number; replayed: boolean }
453	  /** 3-D Secure or equivalent: the customer must approve it with their bank. */
454	  | { ok: false; kind: "requires_action"; paymentIntentId: string | null; message: string }
455	  /** The issuer said no. A real dunning event. */
456	  | { ok: false; kind: "declined"; message: string; code?: string }
457	  /** Our side or Stripe's side wobbled. NOT the customer's fault — never dun for it. */
458	  | { ok: false; kind: "transient"; message: string }
459	  /** Nothing to charge with (no card, Stripe off, amount under Stripe's floor). */
460	  | { ok: false; kind: "unavailable"; message: string };
461	
462	/**
463	 * Stable per-purpose marker written into PaymentIntent metadata.
464	 *
465	 * This is a SECOND idempotency guard that does not expire. Stripe's own
466	 * idempotency keys are only honoured for 24 hours, and our dunning schedule spans
467	 * six days, so the key alone cannot answer "have we already been paid for this
468	 * period?". Before charging we look for a live PaymentIntent carrying this marker
469	 * and reuse it — so a crash between "Stripe captured the money" and "we recorded
470	 * the payment intent id" can never turn into a second charge.
471	 */
472	export function renewalChargeMarker(serverId: string, periodStart: Date): string {
473	  return `renew:${serverId}:${periodStart.toISOString()}`;
474	}
475	
476	/** Marker for an automatic wallet top-up: at most one per account per day. */
477	export function autoRechargeMarker(userId: string, now: Date): string {
478	  return `autorecharge:${userId}:${now.toISOString().slice(0, 10)}`;
479	}
480	
481	/** Look for a charge we may already have made for this exact purpose. */
482	async function findChargeByMarker(
483	  customerId: string,
484	  marker: string,
485	): Promise<Stripe.PaymentIntent | null> {
486	  // 25 is generous: renewals are monthly and this is scoped to one customer, so a
487	  // charge made minutes or days ago is always inside this window.
488	  const list = await stripe().paymentIntents.list({ customer: customerId, limit: 25 });
489	  const mine = list.data.filter((pi) => pi.metadata?.nxeonChargeKey === marker);
490	  return (
491	    mine.find((pi) => pi.status === "succeeded") ??
492	    mine.find((pi) => pi.status === "requires_action") ??
493	    mine.find((pi) => pi.status === "processing") ??
494	    null
495	  );
496	}
497	
498	/**
499	 * Charge the saved card off-session (no customer present).
500	 *
501	 * Two independent idempotency guards, because this moves real money on a timer
502	 * that retries:
503	 *  1. `marker` — pre-flight lookup of a live PaymentIntent for this exact purpose.
504	 *     Survives forever, catches the crash-after-capture window.
505	 *  2. `idempotencyKey` — Stripe replays the identical request instead of charging
506	 *     twice when two sweeps overlap. Only good for 24h, hence guard 1.
507	 */
508	export async function chargeSavedCardOffSession(opts: {
509	  user: CardUser;
510	  amountCents: number;
511	  description: string;
512	  marker: string;
513	  idempotencyKey: string;
514	  metadata?: Record<string, string>;
515	}): Promise<OffSessionResult> {
516	  const { user, amountCents, description, marker, idempotencyKey } = opts;
517	  if (!stripeConfigured()) return { ok: false, kind: "unavailable", message: "Stripe is not configured" };
518	  if (!user.stripeCustomerId || !user.stripePaymentMethodId) {
519	    return { ok: false, kind: "unavailable", message: "No saved card" };
520	  }
521	  // `walletSplit` already keeps the card leg at or above Stripe's floor; this is
522	  // the belt-and-braces check so a future caller can't send a rejectable amount.
523	  if (amountCents < STRIPE_MIN_CENTS) {
524	    return { ok: false, kind: "unavailable", message: `Below Stripe minimum (${STRIPE_MIN_CENTS}c)` };
525	  }
526	
527	  // Guard 1: did we already charge for this purpose?
528	  try {
529	    const existing = await findChargeByMarker(user.stripeCustomerId, marker);
530	    if (existing?.status === "succeeded") {
531	      return {
532	        ok: true,
533	        paymentIntentId: existing.id,
534	        amountCents: existing.amount_received || existing.amount,
535	        replayed: true,
536	      };
537	    }
538	    if (existing?.status === "requires_action") {
539	      // A 3-D Secure wall does not move: retrying the SAME card off-session hits it
540	      // again, so reuse the existing intent (and its link) rather than piling up a
541	      // new challenge every retry. A DIFFERENT card is a different story — if the
542	      // customer has since saved one, cancel the stale challenge and really try it,
543	      // otherwise saving a new card would silently change nothing.
544	      const pendingPm =
545	        typeof existing.payment_method === "string"
546	          ? existing.payment_method
547	          : (existing.payment_method?.id ?? null);
548	      if (pendingPm === user.stripePaymentMethodId) {
549	        return {
550	          ok: false,
551	          kind: "requires_action",
