645	/**
646	 * Credit the wallet for money a card just paid, exactly once.
647	 *
648	 * Idempotency is the UNIQUE index on `WalletTransaction.stripePaymentIntentId`,
649	 * NOT a read-then-write check: a retried sweep and a replayed Stripe request can
650	 * both arrive with the same intent id, and only the database can safely pick the
651	 * winner. P2002 means someone already credited it — that is a success, not an error.
652	 *
653	 * No invoice for a renewal leg: the renewal transaction issues one PAID invoice
654	 * for the whole renewal, and a second document for the card portion would
655	 * double-count the same revenue. Callers that ARE the whole payment (a wallet
656	 * auto-top-up) pass `invoiceDescription` and get one in the same guarded write.
657	 */
658	export async function creditOffSessionCharge(opts: {
659	  userId: string;
660	  amountCents: number;
661	  description: string;
662	  paymentIntentId: string;
663	  invoiceDescription?: string;
664	}): Promise<boolean> {
665	  if (opts.amountCents <= 0) return false;
666	  try {
667	    await db.$transaction([
668	      db.walletTransaction.create({
669	        data: {
670	          userId: opts.userId,
671	          amountCents: opts.amountCents,
672	          description: opts.description,
673	          stripePaymentIntentId: opts.paymentIntentId,
674	        },
675	      }),
676	      db.user.update({
677	        where: { id: opts.userId },
678	        data: { balanceCents: { increment: opts.amountCents } },
679	      }),
680	      ...(opts.invoiceDescription
681	        ? [
682	            db.invoice.create({
683	              data: invoiceCreateData({
684	                userId: opts.userId,
685	                description: opts.invoiceDescription,
686	                status: "PAID",
687	                lineItems: [
688	                  {
689	                    description: opts.invoiceDescription,
690	                    qty: 1,
691	                    unitCents: opts.amountCents,
692	                    amountCents: opts.amountCents,
693	                  },
694	                ],
695	              }),
696	            }),
697	          ]
698	        : []),
699	    ]);
700	    return true;
701	  } catch (e) {
702	    if ((e as { code?: string })?.code === "P2002") return false; // already credited
703	    throw e;
704	  }
705	}
