240	/** Remind the customer to approve the confirmation email at most this often. */
241	const TRANSFER_NUDGE_DAYS = 3;
242	
243	/**
244	 * Poll every TRANSFER_PENDING domain and move it to its real state.
245	 *
246	 * An ICANN transfer takes ~5-7 days and only completes once the owner approves
247	 * an email from the LOSING registrar, so this is a slow poll, not a spinner:
248	 *   completed -> ACTIVE, dates taken from the registrar, auth code scrubbed
249	 *   failed    -> TRANSFER_FAILED, wallet credited back, reason recorded
250	 *   pending   -> raw registrar status refreshed for display, gentle nudge
251	 *
252	 * Every mutation goes through the shared CAS-guarded settle helpers, so a
253	 * re-run, two workers racing, or a customer cancelling at the same moment can
254	 * never credit the same transfer twice.
255	 */
256	async function domainTransferInSweep(now: Date) {
257	  if (!transfersAvailable()) return; // registrar not configured — skip silently
258	
259	  const pending = await db.domain.findMany({
260	    where: { status: "TRANSFER_PENDING", isTransferIn: true },
261	  });
262	
263	  for (const domain of pending) {
264	    try {
265	      const info = await getTransfer(domain.name, domain.transferStartedAt);
266	
267	      // No transfer on record. Normal once a transfer settles and drops off the
268	      // registrar's list — resolve it against the account rather than guessing.
269	      if (!info) {
270	        const owned = await domainInfo(domain.name).catch(() => null);
271	        if (owned?.expires) {
272	          await completeTransferIn(domain, "completed", owned);
273	          continue;
274	        }
275	        const startedAt = domain.transferStartedAt ?? domain.createdAt;
276	        const ageDays = (now.getTime() - startedAt.getTime()) / DAY;
277	        if (ageDays > TRANSFER_STALE_DAYS) {
278	          await failTransferIn(
279	            domain,
280	            null,
281	            `The registrar has no record of this transfer after ${Math.round(ageDays)} days. It did not complete.`
282	          );
283	        }
284	        continue;
285	      }
286	
287	      const outcome = transferOutcome(info.status);
288	
289	      if (outcome === "completed") {
290	        const owned = await domainInfo(domain.name).catch(() => null);
291	        await completeTransferIn(domain, info.status, owned);
292	        continue;
293	      }
294	
295	      if (outcome === "failed") {
296	        await failTransferIn(domain, info.status, transferStatusLabel(info.status));
297	        continue;
298	      }
299	
300	      // Still in flight — keep the displayed registrar status fresh.
301	      if (info.status !== domain.transferStatus || (info.email && info.email !== domain.transferEmail)) {
302	        await db.domain.update({
303	          where: { id: domain.id },
304	          data: { transferStatus: info.status, ...(info.email ? { transferEmail: info.email } : {}) },
305	        });
306	      }
307	      await nudgeTransferApproval(domain, info.status, info.email, now);
308	    } catch (e) {
309	      // One unhappy domain must never abort the sweep. Nothing is settled and
310	      // no money moves on an unknown state — we simply try again next pass.
