404	/**
405	 * Terminate servers that have been SUSPENDED (unpaid) past the termination window,
406	 * reclaiming disk + dedicated IP. Warns the customer before the final deletion.
407	 * A payment before this point unsuspends the server, so this only ever hits
408	 * genuinely abandoned accounts. Free servers are never terminated.
409	 */
410	async function terminateOverdue(now: Date) {
411	  // ONLY unpaid suspensions. This used to select on `status: "SUSPENDED"` alone,
412	  // while the renewal sweep EXCLUDES suspended servers — so an admin suspending a
413	  // paid-up customer pending an abuse investigation meant that customer was never
414	  // charged and never warned, their term quietly lapsed, and 13 days later this
415	  // function destroyed their VM and all its data with a "prolonged non-payment"
416	  // notice they had never been given the chance to act on. They had auto-renew on
417	  // and money in their wallet the entire time.
418	  //
419	  // Legacy rows suspended before `suspendReason` existed have it null; those are
420	  // deliberately excluded too. Failing to delete is always the safer error here —
421	  // an un-terminated server costs disk, a wrongly-terminated one is unrecoverable.
422	  const suspended = await db.server.findMany({
423	    where: {
424	      isFree: false,
425	      status: "SUSPENDED",
426	      suspendReason: "UNPAID",
427	      expiresAt: { not: null },
428	    },
429	  });
430	  for (const server of suspended) {
431	    const terminateAt = server.expiresAt!.getTime() + (GRACE_DAYS + TERMINATE_DAYS) * DAY;
432	    const warnAt = terminateAt - WARN_BEFORE_TERMINATE_DAYS * DAY;
433	
434	    if (now.getTime() >= terminateAt) {
435	      const pending = await db.job.count({
436	        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
437	      });
438	      if (pending > 0) continue;
439	      await db.server.update({ where: { id: server.id }, data: { status: "DELETING" } });
440	      await db.job.create({ data: { type: "DELETE", serverId: server.id } });
441	      await db.auditLog.create({
442	        data: { userId: server.userId, action: "billing.terminated_unpaid", detail: server.id },
443	      });
444	      await db.notification.create({
445	        data: {
446	          userId: server.userId,
447	          title: `${server.hostname} was permanently deleted`,
448	          body: "Your server and its data were removed after prolonged non-payment.",
449	        },
450	      });
451	      console.log(`[billing] terminating abandoned ${server.hostname}`);
452	    } else if (now.getTime() >= warnAt) {
453	      const already = await db.notification.findFirst({
454	        where: {
455	          userId: server.userId,
456	          title: { contains: server.hostname },
457	          AND: { title: { contains: "will be deleted" } },
458	          createdAt: { gt: new Date(now.getTime() - 2 * DAY) },
459	        },
460	      });
461	      if (!already) {
462	        await db.notification.create({
463	          data: {
464	            userId: server.userId,
465	            title: `${server.hostname} will be deleted soon`,
466	            body: `This suspended server and all its data will be permanently deleted on ${new Date(terminateAt).toISOString().slice(0, 10)} unless you pay. Restore it now from your billing page.`,
467	            href: `/dashboard/servers/${server.id}`,
468	          },
469	        });
470	      }
471	    }
472	  }
473	}
