475	/**
476	 * Auto-renew domains expiring within 7 days when the owner opted in and has
477	 * the funds. Charges the wallet, extends expiry +365d and notifies the owner.
478	 * Failures (registrar error, misconfig) notify the owner to renew manually and
479	 * never charge the wallet.
480	 */
481	async function domainAutoRenewSweep(now: Date) {
482	  if (!registrarConfigured()) return; // registrar not configured — skip silently
483	
484	  const cutoff = new Date(now.getTime() + DOMAIN_RENEW_WINDOW_DAYS * 86400_000);
485	  const domains = await db.domain.findMany({
486	    where: {
487	      autoRenew: true,
488	      status: "ACTIVE",
489	      expiresAt: { not: null, lt: cutoff },
490	    },
491	    include: { user: true },
492	  });
493	
494	  for (const domain of domains) {
495	    if (!domain.expiresAt) continue;
496	    const dTerm = domainTerm(domain.termYears);
497	    const dRenewCents = domainTermPriceCents(domain.priceCents, dTerm.years); // retail (customer)
498	    const dRegistrarCost = (domain.costCents || domain.priceCents) * dTerm.years; // cost (registrar)
499	    if (domain.user.balanceCents < dRenewCents) {
500	      const already = await db.notification.findFirst({
501	        where: {
502	          userId: domain.userId,
503	          title: { contains: domain.name },
504	          AND: { title: { contains: "auto-renew failed" } },
505	          createdAt: { gt: new Date(now.getTime() - 3 * 86400_000) },
506	        },
507	      });
508	      if (!already) {
509	        await db.notification.create({
510	          data: {
511	            userId: domain.userId,
512	            title: `${domain.name} auto-renew failed — top up to renew`,
513	            body: `Renewal is $${(dRenewCents / 100).toFixed(2)} (${dTerm.label}) but your balance is $${(domain.user.balanceCents / 100).toFixed(2)}. Top up and renew manually before ${domain.expiresAt.toISOString().slice(0, 10)}.`,
514	            href: `/dashboard/domains`,
515	          },
516	        });
517	      }
518	      continue;
519	    }
520	
521	    try {
522	      await renewDomain(domain.name, dTerm.years, dRegistrarCost);
523	    } catch (e) {
524	      console.error(`[billing] domain auto-renew failed for ${domain.name}`, e);
525	      await db.notification.create({
526	        data: {
527	          userId: domain.userId,
528	          title: `${domain.name} auto-renew failed — please renew manually`,
529	          body: `We couldn't renew ${domain.name} automatically: ${String((e as any)?.message ?? e).slice(0, 200)}. Renew it manually from your domains page.`,
530	          href: `/dashboard/domains`,
531	        },
532	      });
533	      continue;
534	    }
535	
536	    const newExpiry = new Date(domain.expiresAt.getTime() + dTerm.years * 365 * 86400_000);
537	    // The registrar renewal already succeeded above, so the cost is committed.
538	    // Charge with the guarded debit (the loop's snapshot balance is stale), and
539	    // CAS the expiry so a concurrent manual renew can't be charged twice. If the
540	    // wallet can't cover it we must STILL record the renewal we paid for — flag it
541	    // as uncharged for ops rather than silently eating it or renewing twice later.
542	    try {
543	      await db.$transaction(async (tx) => {
544	        const advanced = await tx.domain.updateMany({
545	          where: { id: domain.id, expiresAt: domain.expiresAt },
546	          data: { expiresAt: newExpiry },
547	        });
548	        if (advanced.count === 0) throw new AlreadyRenewedError();
549	        await debitWallet(tx, domain.userId, dRenewCents);
550	        await tx.walletTransaction.create({
551	          data: {
552	            userId: domain.userId,
553	            amountCents: -dRenewCents,
554	            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
555	          },
556	        });
557	        // PAID invoice on the successfully-charged path only (the uncharged
558	        // InsufficientBalance branch below deliberately makes no invoice). Inside
559	        // the CAS-guarded tx, so a repeated sweep rolls it back with the debit.
560	        await tx.invoice.create({
561	          data: invoiceCreateData({
562	            userId: domain.userId,
563	            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
564	            status: "PAID",
565	            period: { start: domain.expiresAt, end: newExpiry },
566	            lineItems: [
567	              { description: `Domain renewal — ${domain.name} (${dTerm.label})`, qty: 1, unitCents: dRenewCents, amountCents: dRenewCents },
568	            ],
569	          }),
570	        });
571	        await tx.auditLog.create({
572	          data: { userId: domain.userId, action: "domain.auto_renewed", detail: domain.name },
573	        });
574	      });
575	    } catch (e) {
576	      if (e instanceof AlreadyRenewedError) {
577	        continue; // someone already advanced this period
578	      }
579	      if (e instanceof InsufficientBalanceError) {
580	        await db.domain.update({ where: { id: domain.id }, data: { expiresAt: newExpiry } });
581	        await db.auditLog.create({
582	          data: {
583	            userId: domain.userId,
584	            action: "domain.renew.uncharged",
585	            detail: `${domain.name}: renewed at registrar but wallet could not be charged ${dRenewCents}c — collect manually`,
586	          },
587	        });
588	        console.error(`[billing] UNCHARGED domain renewal for ${domain.name} (insufficient balance)`);
589	        continue;
590	      }
591	      throw e;
592	    }
593	    await db.notification.create({
594	      data: {
595	        userId: domain.userId,
596	        title: `${domain.name} renewed automatically`,
597	        body: `Charged $${(domain.priceCents / 100).toFixed(2)}. New expiry: ${newExpiry.toISOString().slice(0, 10)}.`,
598	        href: `/dashboard/domains`,
599	      },
600	    });
601	    console.log(`[billing] auto-renewed domain ${domain.name} until ${newExpiry.toISOString()}`);
602	  }
603	}
