74	/** Days past expiry of the LAST automatic retry. */
75	const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);
76	/** One clear day between the final-notice email and the suspension it warns about. */
77	const CARD_SUSPEND_DAY = LAST_RETRY_DAY + 1;
78	/** `Server.dunningStage` once the attempt on expiry day AND every retry have failed. */
79	const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;
80	/**
81	 * Never schedule a retry sooner than this. The sweep runs every 10 minutes, so a
82	 * worker that was down for a week would otherwise burn every retry — and every
83	 * email — in the space of one afternoon.
84	 */
85	const MIN_RETRY_GAP_MS = 20 * 3600_000;
86	/** How soon to re-try after an error that was OUR side, not the customer's. */
87	const TRANSIENT_RETRY_MS = 60 * 60_000;
