98	 * Dunning windows, all measured in DAYS PAST EXPIRY.
99	 *
100	 * Settings → Billing is the source of truth. Those three fields and the
101	 * "Auto-suspend overdue accounts" toggle used to be written to the Setting table and
102	 * read by NOTHING: the worker used env vars that were never set, so an operator who
103	 * turned suspensions off during an incident saw "Saved." and then watched the sweep
104	 * knock customer VMs offline ten minutes later.
105	 *
106	 * The legacy env vars remain as fallbacks, converted onto the days-past-expiry clock
107	 * so an operator who had set them keeps the behaviour they configured
108	 * (NXEON_TERMINATE_DAYS counted forward from the END of grace, and
109	 * NXEON_WARN_BEFORE_TERMINATE_DAYS counted backwards from termination).
110	 */
111	type DunningConfig = {
112	  /** Days past expiry before an account with no card in play is suspended. */
113	  graceDays: number;
114	  /** Days past expiry when the "will be deleted" warning goes out. */
115	  warnDays: number;
116	  /** Days past expiry when an unpaid SUSPENDED server is destroyed. */
117	  terminateDays: number;
118	  /** Admin kill switch: when false the sweep suspends and terminates nothing. */
119	  autoSuspend: boolean;
120	};
