122	const ENV_GRACE_DAYS = Number(process.env.NXEON_GRACE_DAYS ?? 3);
123	const ENV_TERMINATE_DAYS = process.env.NXEON_TERMINATE_DAYS
124	  ? ENV_GRACE_DAYS + Number(process.env.NXEON_TERMINATE_DAYS)
125	  : 14;
126	const ENV_WARN_DAYS = process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS
127	  ? ENV_TERMINATE_DAYS - Number(process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS)
