130	async function dunningConfig(): Promise<DunningConfig> {
131	  const graceDays = Math.max(0, await getSettingInt("dunning_grace_days", ENV_GRACE_DAYS));
132	  let terminateDays = await getSettingInt("dunning_terminate_days", ENV_TERMINATE_DAYS);
133	  let warnDays = await getSettingInt("dunning_warn_days", ENV_WARN_DAYS);
134	  const autoSuspend = await getSettingBool("auto_suspend_enabled", true);
135	
136	  // Clamp. These are free-text number fields in an admin panel and the action they
137	  // gate is irreversible — a typo (or a 0) must never be able to destroy a VM on the
138	  // same day it is suspended, or before the dunning sequence has even finished.
139	  terminateDays = Math.max(terminateDays, Math.max(graceDays, CARD_SUSPEND_DAY) + 1);
140	  warnDays = Math.min(Math.max(warnDays, 1), terminateDays - 1);
141	  return { graceDays, warnDays, terminateDays, autoSuspend };
142	}
