225	    const already = await db.notification.findFirst({
226	      where: {
227	        userId: server.userId,
228	        title: { contains: server.hostname },
229	        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
230	        AND: { title: { contains: "renews soon" } },
231	      },
232	    });
233	    if (!already) {
234	      await db.notification.create({
235	        data: {
236	          userId: server.userId,
237	          title: `${server.hostname} renews soon — action needed`,
238	          body: server.autoRenew
239	            ? `Renewal is $${(warnCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
240	            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
241	          href: `/dashboard/servers/${server.id}`,
242	        },
243	      });
244	    }
245	  }
246	  const due = await dueServers(now);
247	
248	  for (const server of due) {
249	    const charge = renewalCharge(server, prices);
250	    const renewCents = charge.totalCents;
251	    const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
252	    const newExpiry = addMonths(base, charge.months);
253	
254	    let renewed = false;
255	    if (server.autoRenew) {
256	      // `server.user.balanceCents` came from a snapshot taken before this loop and
257	      // is stale as soon as the first renewal in this pass debits a wallet, so the
258	      // SPLIT is computed from a fresh read. It is still never a gate: `debitWallet`
259	      // re-checks funds atomically and the compare-and-swap on `expiresAt` stops a
260	      // concurrent renewNow()/second pass charging the same period twice.
261	      const fresh = await db.user.findUnique({
262	        where: { id: server.userId },
263	        select: { balanceCents: true },
264	      });
265	      const split = walletSplit({
266	        dueCents: renewCents,
267	        balanceCents: fresh?.balanceCents ?? 0,
268	        useWallet: true,
269	      });
270	      const cardInPlay = hasChargeableCard(server.user);
271	
272	      if (split.cardCents === 0) {
273	        // Wallet covers the whole renewal — no card involved, no Stripe call.
274	        const outcome = await commitRenewal({ server, charge, newExpiry });
275	        renewed = outcome !== "insufficient";
276	        if (outcome === "renewed") {
277	          console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
278	        }
279	      } else if (cardInPlay) {
280	        // Only attempt on the scheduled day. Without this gate a 10-minute sweep
281	        // would burn all three retries — and send all three emails — within half an
282	        // hour of the first decline.
283	        const dueForRetry =
284	          server.dunningStage < DUNNING_EXHAUSTED &&
285	          (!server.dunningNextAt || now >= server.dunningNextAt);
286	        if (dueForRetry) {
287	          renewed = await attemptCardRenewal({
288	            server,
289	            charge,
290	            cardCents: split.cardCents,
291	            newExpiry,
292	            now,
293	            cfg,
294	          });
295	        }
296	      } else {
297	        console.log(
298	          `[billing] ${server.hostname} short by ${fmtUsd(split.cardCents)} and no card on file — grace/suspend applies`,
299	        );
300	      }
301	    }
302	
303	    if (renewed) {
304	      // nothing further this pass
305	    } else {
306	      const suspendAt = suspendDueAt(server, hasChargeableCard(server.user), cfg);
307	      if (suspendAt && now >= suspendAt) {
308	        await suspendUnpaid(server, cfg);
309	      }
310	    }
311	  }
312	
313	  await terminateOverdue(now, cfg);
314	
315	  // Card housekeeping: nudge before a saved card expires, and honour the customer's
316	  // own automatic top-up preference. Both are isolated so a Stripe or SMTP problem
317	  // can never take the renewal sweep down with it.
318	  try {
319	    await cardExpirySweep(now);
320	  } catch (e) {
321	    console.error("[billing] card-expiry sweep error", e);
322	  }
323	  try {
324	    await autoRechargeSweep(now);
325	  } catch (e) {
326	    console.error("[billing] auto-recharge sweep error", e);
327	  }
328	
329	  await domainAutoRenewSweep(now);
330	
331	  // Poll in-flight inbound transfers on the same cadence as domain renewals —
332	  // domain upkeep all lives on one timer.
333	  try {
334	    await domainTransferInSweep(now);
335	  } catch (e) {
336	    console.error("[billing] domain transfer-in sweep error", e);
337	  }
338	}
