340	/* ------------------------------------------------------------------ *
341	 * Inbound domain transfers (transfer-in)
342	 * ------------------------------------------------------------------ */
343	
344	/** Remind the customer to approve the confirmation email at most this often. */
345	const TRANSFER_NUDGE_DAYS = 3;
346	
347	/**
348	 * Poll every TRANSFER_PENDING domain and move it to its real state.
349	 *
350	 * An ICANN transfer takes ~5-7 days and only completes once the owner approves
351	 * an email from the LOSING registrar, so this is a slow poll, not a spinner:
352	 *   completed -> ACTIVE, dates taken from the registrar, auth code scrubbed
353	 *   failed    -> TRANSFER_FAILED, wallet credited back, reason recorded
354	 *   pending   -> raw registrar status refreshed for display, gentle nudge
355	 *
356	 * Every mutation goes through the shared CAS-guarded settle helpers, so a
357	 * re-run, two workers racing, or a customer cancelling at the same moment can
358	 * never credit the same transfer twice.
359	 */
360	async function domainTransferInSweep(now: Date) {
361	  if (!transfersAvailable()) return; // registrar not configured — skip silently
362	
363	  const pending = await db.domain.findMany({
364	    where: { status: "TRANSFER_PENDING", isTransferIn: true },
365	  });
366	
367	  for (const domain of pending) {
368	    try {
369	      const info = await getTransfer(domain.name, domain.transferStartedAt);
370	
371	      // No transfer on record. Normal once a transfer settles and drops off the
372	      // registrar's list — resolve it against the account rather than guessing.
373	      if (!info) {
374	        const owned = await domainInfo(domain.name).catch(() => null);
375	        if (owned?.expires) {
376	          await completeTransferIn(domain, "completed", owned);
377	          continue;
378	        }
379	        const startedAt = domain.transferStartedAt ?? domain.createdAt;
380	        const ageDays = (now.getTime() - startedAt.getTime()) / DAY;
381	        if (ageDays > TRANSFER_STALE_DAYS) {
382	          await failTransferIn(
383	            domain,
384	            null,
385	            `The registrar has no record of this transfer after ${Math.round(ageDays)} days. It did not complete.`
386	          );
387	        }
388	        continue;
389	      }
390	
391	      const outcome = transferOutcome(info.status);
392	
393	      if (outcome === "completed") {
394	        const owned = await domainInfo(domain.name).catch(() => null);
395	        await completeTransferIn(domain, info.status, owned);
396	        continue;
397	      }
398	
399	      if (outcome === "failed") {
400	        await failTransferIn(domain, info.status, transferStatusLabel(info.status));
401	        continue;
402	      }
403	
404	      // Still in flight — keep the displayed registrar status fresh.
405	      if (info.status !== domain.transferStatus || (info.email && info.email !== domain.transferEmail)) {
406	        await db.domain.update({
407	          where: { id: domain.id },
408	          data: { transferStatus: info.status, ...(info.email ? { transferEmail: info.email } : {}) },
409	        });
410	      }
411	      await nudgeTransferApproval(domain, info.status, info.email, now);
412	    } catch (e) {
413	      // One unhappy domain must never abort the sweep. Nothing is settled and
414	      // no money moves on an unknown state — we simply try again next pass.
415	      console.error(`[billing] transfer-in poll failed for ${domain.name}`, e);
416	    }
417	  }
418	}
