508	/**
509	 * Terminate servers that have been SUSPENDED (unpaid) past the termination window,
510	 * reclaiming disk + dedicated IP. Warns the customer before the final deletion.
511	 * A payment before this point unsuspends the server, so this only ever hits
512	 * genuinely abandoned accounts. Free servers are never terminated.
513	 */
514	async function terminateOverdue(now: Date) {
515	  // ONLY unpaid suspensions. This used to select on `status: "SUSPENDED"` alone,
516	  // while the renewal sweep EXCLUDES suspended servers — so an admin suspending a
517	  // paid-up customer pending an abuse investigation meant that customer was never
518	  // charged and never warned, their term quietly lapsed, and 13 days later this
519	  // function destroyed their VM and all its data with a "prolonged non-payment"
520	  // notice they had never been given the chance to act on. They had auto-renew on
521	  // and money in their wallet the entire time.
522	  //
523	  // Legacy rows suspended before `suspendReason` existed have it null; those are
524	  // deliberately excluded too. Failing to delete is always the safer error here —
525	  // an un-terminated server costs disk, a wrongly-terminated one is unrecoverable.
526	  const suspended = await db.server.findMany({
527	    where: {
528	      isFree: false,
529	      status: "SUSPENDED",
530	      suspendReason: "UNPAID",
531	      expiresAt: { not: null },
532	    },
533	  });
534	  for (const server of suspended) {
535	    const terminateAt = server.expiresAt!.getTime() + (GRACE_DAYS + TERMINATE_DAYS) * DAY;
536	    const warnAt = terminateAt - WARN_BEFORE_TERMINATE_DAYS * DAY;
537	
538	    if (now.getTime() >= terminateAt) {
539	      const pending = await db.job.count({
540	        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
541	      });
542	      if (pending > 0) continue;
543	      await db.server.update({ where: { id: server.id }, data: { status: "DELETING" } });
544	      await db.job.create({ data: { type: "DELETE", serverId: server.id } });
545	      await db.auditLog.create({
546	        data: { userId: server.userId, action: "billing.terminated_unpaid", detail: server.id },
547	      });
548	      await db.notification.create({
549	        data: {
550	          userId: server.userId,
551	          title: `${server.hostname} was permanently deleted`,
552	          body: "Your server and its data were removed after prolonged non-payment.",
553	        },
554	      });
555	      console.log(`[billing] terminating abandoned ${server.hostname}`);
556	    } else if (now.getTime() >= warnAt) {
557	      const already = await db.notification.findFirst({
558	        where: {
559	          userId: server.userId,
560	          title: { contains: server.hostname },
561	          AND: { title: { contains: "will be deleted" } },
562	          createdAt: { gt: new Date(now.getTime() - 2 * DAY) },
563	        },
564	      });
565	      if (!already) {
566	        await db.notification.create({
567	          data: {
568	            userId: server.userId,
569	            title: `${server.hostname} will be deleted soon`,
570	            body: `This suspended server and all its data will be permanently deleted on ${new Date(terminateAt).toISOString().slice(0, 10)} unless you pay. Restore it now from your billing page.`,
571	            href: `/dashboard/servers/${server.id}`,
572	          },
573	        });
574	      }
575	    }
576	  }
577	}
