579	/**
580	 * Auto-renew domains expiring within 7 days when the owner opted in and has
581	 * the funds. Charges the wallet, extends expiry +365d and notifies the owner.
582	 * Failures (registrar error, misconfig) notify the owner to renew manually and
583	 * never charge the wallet.
584	 */
585	async function domainAutoRenewSweep(now: Date) {
586	  if (!registrarConfigured()) return; // registrar not configured — skip silently
587	
588	  const cutoff = new Date(now.getTime() + DOMAIN_RENEW_WINDOW_DAYS * 86400_000);
589	  const domains = await db.domain.findMany({
590	    where: {
591	      autoRenew: true,
592	      status: "ACTIVE",
593	      expiresAt: { not: null, lt: cutoff },
594	    },
595	    include: { user: true },
596	  });
597	
598	  for (const domain of domains) {
599	    if (!domain.expiresAt) continue;
600	    const dTerm = domainTerm(domain.termYears);
601	    const dRenewCents = domainTermPriceCents(domain.priceCents, dTerm.years); // retail (customer)
602	    const dRegistrarCost = (domain.costCents || domain.priceCents) * dTerm.years; // cost (registrar)
603	    if (domain.user.balanceCents < dRenewCents) {
604	      const already = await db.notification.findFirst({
605	        where: {
606	          userId: domain.userId,
607	          title: { contains: domain.name },
608	          AND: { title: { contains: "auto-renew failed" } },
609	          createdAt: { gt: new Date(now.getTime() - 3 * 86400_000) },
610	        },
611	      });
612	      if (!already) {
613	        await db.notification.create({
614	          data: {
615	            userId: domain.userId,
616	            title: `${domain.name} auto-renew failed — top up to renew`,
617	            body: `Renewal is $${(dRenewCents / 100).toFixed(2)} (${dTerm.label}) but your balance is $${(domain.user.balanceCents / 100).toFixed(2)}. Top up and renew manually before ${domain.expiresAt.toISOString().slice(0, 10)}.`,
618	            href: `/dashboard/domains`,
619	          },
620	        });
621	      }
622	      continue;
623	    }
624	
625	    try {
626	      await renewDomain(domain.name, dTerm.years, dRegistrarCost);
627	    } catch (e) {
628	      console.error(`[billing] domain auto-renew failed for ${domain.name}`, e);
629	      await db.notification.create({
630	        data: {
631	          userId: domain.userId,
632	          title: `${domain.name} auto-renew failed — please renew manually`,
633	          body: `We couldn't renew ${domain.name} automatically: ${String((e as any)?.message ?? e).slice(0, 200)}. Renew it manually from your domains page.`,
634	          href: `/dashboard/domains`,
635	        },
636	      });
637	      continue;
638	    }
639	
640	    const newExpiry = new Date(domain.expiresAt.getTime() + dTerm.years * 365 * 86400_000);
641	    // The registrar renewal already succeeded above, so the cost is committed.
642	    // Charge with the guarded debit (the loop's snapshot balance is stale), and
643	    // CAS the expiry so a concurrent manual renew can't be charged twice. If the
644	    // wallet can't cover it we must STILL record the renewal we paid for — flag it
645	    // as uncharged for ops rather than silently eating it or renewing twice later.
646	    try {
647	      await db.$transaction(async (tx) => {
648	        const advanced = await tx.domain.updateMany({
649	          where: { id: domain.id, expiresAt: domain.expiresAt },
650	          data: { expiresAt: newExpiry },
651	        });
652	        if (advanced.count === 0) throw new AlreadyRenewedError();
653	        await debitWallet(tx, domain.userId, dRenewCents);
654	        await tx.walletTransaction.create({
655	          data: {
656	            userId: domain.userId,
657	            amountCents: -dRenewCents,
658	            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
659	          },
660	        });
661	        // PAID invoice on the successfully-charged path only (the uncharged
662	        // InsufficientBalance branch below deliberately makes no invoice). Inside
663	        // the CAS-guarded tx, so a repeated sweep rolls it back with the debit.
664	        await tx.invoice.create({
665	          data: invoiceCreateData({
666	            userId: domain.userId,
667	            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
668	            status: "PAID",
669	            period: { start: domain.expiresAt, end: newExpiry },
670	            lineItems: [
671	              { description: `Domain renewal — ${domain.name} (${dTerm.label})`, qty: 1, unitCents: dRenewCents, amountCents: dRenewCents },
672	            ],
673	          }),
674	        });
675	        await tx.auditLog.create({
676	          data: { userId: domain.userId, action: "domain.auto_renewed", detail: domain.name },
677	        });
678	      });
679	    } catch (e) {
680	      if (e instanceof AlreadyRenewedError) {
681	        continue; // someone already advanced this period
682	      }
683	      if (e instanceof InsufficientBalanceError) {
684	        await db.domain.update({ where: { id: domain.id }, data: { expiresAt: newExpiry } });
685	        await db.auditLog.create({
686	          data: {
687	            userId: domain.userId,
688	            action: "domain.renew.uncharged",
689	            detail: `${domain.name}: renewed at registrar but wallet could not be charged ${dRenewCents}c — collect manually`,
690	          },
691	        });
692	        console.error(`[billing] UNCHARGED domain renewal for ${domain.name} (insufficient balance)`);
693	        continue;
694	      }
695	      throw e;
696	    }
697	    await db.notification.create({
698	      data: {
699	        userId: domain.userId,
700	        title: `${domain.name} renewed automatically`,
701	        body: `Charged $${(domain.priceCents / 100).toFixed(2)}. New expiry: ${newExpiry.toISOString().slice(0, 10)}.`,
702	        href: `/dashboard/domains`,
703	      },
704	    });
705	    console.log(`[billing] auto-renewed domain ${domain.name} until ${newExpiry.toISOString()}`);
706	  }
707	}
