48	function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
49	  if (!c.host) {
50	    // Local MTA fallback (Postfix/sendmail on the host)
51	    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
52	  }
53	  // When the SMTP host is an internal IP (e.g. the mail VM at 10.20.0.10) but the
54	  // server presents a cert for its hostname (mail.nxeon.cloud), TLS validation
55	  // fails on an IP mismatch. `SMTP_TLS_SERVERNAME` lets us keep cert verification
56	  // on while telling TLS the name to validate against (and sets SNI accordingly).
57	  const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
58	  return nodemailer.createTransport({
59	    host: c.host,
60	    port: c.port,
61	    secure: c.secure,
62	    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
63	    ...(servername ? { tls: { servername } } : {}),
64	  });
65	}
