// Pure, dependency-free wallet/card split math shared by the client wizards
// (DeployWizard, ResizePicker) and the server actions (payAndDeploy,
// resizeServer). Keeping it here — with NO server-only imports — guarantees the
// split the customer SEES is byte-for-byte the split that gets CHARGED.

/**
 * Stripe rejects card charges under ~$0.50. We never send a card amount below
 * this; when the natural remainder would fall under it we leave exactly this
 * much on the card and apply slightly less wallet credit (see walletSplit).
 */
export const STRIPE_MIN_CENTS = 50;

export type WalletSplit = {
  /** Cents taken from the customer's existing wallet balance. */
  walletApplied: number;
  /** Cents charged to the card (0 = fully paid from wallet, no Stripe). */
  cardCents: number;
  /** True when we bumped the card up to STRIPE_MIN_CENTS (reducing wallet). */
  clampedForStripeMin: boolean;
};

/**
 * Split a due amount between the wallet and the card, honoring the customer's
 * "apply my balance" toggle and Stripe's minimum-charge floor.
 *
 * - `useWallet` off  → everything on the card.
 * - wallet covers all → cardCents = 0 (caller pays entirely from wallet, no Stripe).
 * - partial cover     → walletApplied = min(balance, due), card = the remainder.
 * - tiny remainder    → if 0 < card < STRIPE_MIN_CENTS and the wallet can't cover
 *   the whole thing, reduce walletApplied so exactly STRIPE_MIN_CENTS lands on the
 *   card (never send Stripe a sub-minimum charge). Integer-cent exact throughout.
 */
export function walletSplit(opts: {
  dueCents: number;
  balanceCents: number;
  useWallet: boolean;
}): WalletSplit {
  const dueCents = Math.max(0, Math.round(opts.dueCents));
  const balanceCents = Math.max(0, Math.round(opts.balanceCents));
  if (dueCents <= 0) return { walletApplied: 0, cardCents: 0, clampedForStripeMin: false };

  let walletApplied = opts.useWallet ? Math.min(balanceCents, dueCents) : 0;
  let cardCents = dueCents - walletApplied;
  let clampedForStripeMin = false;

  // A tiny non-zero card remainder that Stripe would reject. This only happens
  // when the wallet can't cover the whole charge (otherwise cardCents === 0), so
  // the least-surprising fix is to leave STRIPE_MIN_CENTS on the card and apply a
  // touch less wallet. Guarded so walletApplied can never go negative.
  if (cardCents > 0 && cardCents < STRIPE_MIN_CENTS && dueCents >= STRIPE_MIN_CENTS) {
    walletApplied = dueCents - STRIPE_MIN_CENTS;
    cardCents = STRIPE_MIN_CENTS;
    clampedForStripeMin = true;
  }
  return { walletApplied, cardCents, clampedForStripeMin };
}
