import { walletSplit } from "./wallet-split";
import { dedicatedIpMonthlyCents } from "./dedicated-ip";
import { extraDiskPerGbCents } from "./disk-expand";
import {
  CARD_REMOVED,
  CARD_SETUP_STARTED,
  cardDisplayLabel,
  createCardSetupSession,
  createOutstandingCheckout,
  detachSavedCard,
  renewalCharge,
  retryDunningNow,
  saveCardFromSetupSession,
} from "./stripe-cards";

/**
 * Begin saving a card. Returns the hosted Checkout URL for the browser to follow.
 *
 * The `card.setup_started` audit row is not just bookkeeping: it is the evidence
 * `adoptUnclaimedCards` requires before it will adopt a card that is attached at
 * Stripe but was never confirmed here, which is what keeps a REMOVED card from
 * being silently resurrected.
 */
export async function startCardSetup(): Promise<{ url?: string; error?: string }> {
  // An admin impersonating a customer must not be able to put a card on their
  // account — the same reasoning that blocks impersonated wallet spend.
  await assertNotImpersonating();
  const user = await requireUser();
  if (!stripeConfigured()) {
    return { error: "Card payments aren't configured on this installation yet." };
  }
  try {
    const url = await createCardSetupSession(user);
    if (!url) return { error: "Stripe didn't return a setup link. Please try again." };
    await db.auditLog.create({ data: { userId: user.id, action: CARD_SETUP_STARTED } });
    return { url };
  } catch (e) {
    console.error("[payment-method] setup session failed", e);
    return { error: "We couldn't start card setup just now. Please try again in a moment." };
  }
}

/**
 * Finish saving a card after Stripe redirects back.
 *
 * Safe to call repeatedly with the same session id — it re-reads the same payment
 * method from Stripe and writes the same columns, so a refreshed tab is a no-op
 * rather than a second card.
 */
export async function finalizeCardSetup(
  sessionId: string,
): Promise<{ ok?: boolean; label?: string; error?: string }> {
  await assertNotImpersonating();
  const user = await requireUser();
  if (!sessionId) return { error: "Missing card setup reference." };

  const res = await saveCardFromSetupSession(sessionId, user.id);
  if (res.error || !res.card) return { error: res.error ?? "The card wasn't saved." };

  const label = cardDisplayLabel(res.card) ?? "Card saved";
  await db.auditLog.create({ data: { userId: user.id, action: "card.saved", detail: label } });
  // Anyone mid-dunning was told we'd charge a new card straight away; make it true.
  const requeued = await retryDunningNow(user.id);
  if (requeued > 0) {
    await db.notification.create({
      data: {
        userId: user.id,
        title: "Card saved — we'll retry your renewal shortly",
        body: `We'll charge ${label} for the outstanding renewal within the next few minutes. Nothing is suspended.`,
        href: "/dashboard/billing",
      },
    });
  }
  revalidatePath("/dashboard/billing");
  return { ok: true, label };
}

/** Remove the card on file (detaches at Stripe first — see `detachSavedCard`). */
export async function removeSavedCard(): Promise<{ ok?: boolean; error?: string }> {
  await assertNotImpersonating();
  const user = await requireUser();
  const label = cardDisplayLabel({
    brand: user.cardBrand,
    last4: user.cardLast4,
    expMonth: user.cardExpMonth,
    expYear: user.cardExpYear,
  });
  const res = await detachSavedCard(user.id);
  if (res.error) return { error: res.error };
  await db.auditLog.create({
    data: { userId: user.id, action: CARD_REMOVED, detail: label ?? "card on file" },
  });
  revalidatePath("/dashboard/billing");
  return { ok: true };
}

/**
 * Mint a FRESH hosted-Checkout link for a server's outstanding renewal balance.
 *
 * A link is minted on demand rather than reusing the stored `dunningPayUrl`
 * because Stripe Checkout sessions expire within 24 hours while the dunning
 * sequence runs for six days — surfacing the stored link in the portal would show
 * an expired Stripe page to a customer trying to pay us.
 */
export async function settleOutstanding(
  serverId: string,
): Promise<{ url?: string; error?: string; covered?: boolean }> {
  const user = await requireUser();
  if (!stripeConfigured()) {
    return { error: "Card payments aren't configured — add funds to your wallet instead." };
  }
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { plan: true, gamePlan: true, dedicatedIp: true },
  });
  if (!server) return { error: "Server not found." };
  if (server.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden" };
  if (server.isFree || !server.expiresAt) return { error: "This server has nothing outstanding." };

  const charge = renewalCharge(server, {
    ipMonthlyCents: await dedicatedIpMonthlyCents(),
    extraDiskPerGbCents: await extraDiskPerGbCents(),
  });
  // Wallet credit first, card for the remainder — the same split the sweep will
  // apply, so the quote here and the charge there can never disagree.
  const split = walletSplit({
    dueCents: charge.totalCents,
    balanceCents: user.balanceCents,
    useWallet: true,
  });
  if (split.cardCents === 0) {
    return {
      covered: true,
      error: "Your wallet already covers this renewal — it completes automatically within a few minutes.",
    };
  }

  const url = await createOutstandingCheckout({
    user,
    amountCents: split.cardCents,
    hostname: server.hostname,
    serverId: server.id,
  });
  if (!url) return { error: "We couldn't start checkout just now. Please try again in a moment." };
  // Keep the stored link current for the dunning emails and admin visibility.
  await db.server.update({ where: { id: server.id }, data: { dunningPayUrl: url } });
  return { url };
}

