export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
  // Spend path: block wallet debits while an admin is impersonating.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);
  if (server.isFree || !server.expiresAt) return;
  const plan = await db.plan.findUnique({ where: { id: server.planId } });
  if (!plan) return;
  const term = vpsTerm(server.termMonths);
  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
    where: { serverId }, select: { id: true },
  }));
  // Extra root disk renews at the current per-GB price on top of the plan, exactly
  // like worker/billing.ts — the two renewal paths must never disagree.
  const extraDiskMonthly = await extraDiskMonthlyCents(server.extraDiskGB);
  const extraDiskCents = extraDiskMonthly * term.months;
  const renewCents =
    vpsTermPriceCents(plan.priceCents, term.months) +
    (hasDedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0) +
    extraDiskCents;
  const owner = await db.user.findUnique({ where: { id: server.userId } });
  if (!owner || owner.balanceCents < renewCents) {
    return { error: "Insufficient balance — top up your wallet first." };
  }

  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
  // can't both read E, both debit, and both write E+term (double-charge, one
  // term granted). Only the CAS that matches E wins; the loser is a no-op.
  const E = server.expiresAt;
  const base = new Date(Math.max(E.getTime(), Date.now()));
  const newExpiry = addMonths(base, term.months);
  try {
    await db.$transaction(async (tx) => {
      // Compare-and-swap the expiry first; if it no longer equals E another
      // renewal already advanced it — bail without charging (tx rolls back).
      const adv = await tx.server.updateMany({
        where: { id: serverId, expiresAt: E },
        data: { expiresAt: newExpiry, suspendedNote: null, suspendReason: null },
      });
      if (adv.count === 0) throw new AlreadyRenewedError();
      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
      await debitWallet(tx, server.userId, renewCents);
      await tx.walletTransaction.create({
        data: {
          userId: server.userId,
          amountCents: -renewCents,
          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
        },
      });
      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
      await tx.invoice.create({
        data: invoiceCreateData({
          userId: server.userId,
          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
          status: "PAID",
          period: { start: E, end: newExpiry },
          lineItems: [
            {
              description: `${plan.name} VPS (${server.hostname}) — ${term.label}`,
              qty: 1,
              unitCents: renewCents - extraDiskCents,
              amountCents: renewCents - extraDiskCents,
            },
            ...(extraDiskCents > 0
              ? [
                  {
                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthly / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: extraDiskCents,
                    amountCents: extraDiskCents,
                  },
                ]
              : []),
          ],
        }),
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
    throw e;
  }
  await audit(user.id, "server.renew_now", serverId);

  // An UNPAID-suspended server springs back to life once paid — but only that
