import { db } from "../lib/db";
import {
  registrarConfigured,
  renewDomain,
  transfersAvailable,
  getTransfer,
  domainInfo,
  transferOutcome,
  transferStatusLabel,
} from "../lib/registrar";
import {
  TRANSFER_STALE_DAYS,
  TRANSFER_TERM_YEARS,
  settleCompletedTransferIn,
  settleFailedTransferIn,
} from "../lib/domain-transfer";
import { domainTerm, domainTermPriceCents, addMonths } from "../lib/billing-terms";
import { dedicatedIpMonthlyCents } from "../lib/dedicated-ip";
import { extraDiskPerGbCents } from "../lib/disk-expand";
import { extraDiskLabel } from "../lib/extra-disk";
import { debitWallet, InsufficientBalanceError } from "../lib/wallet";
import { invoiceCreateData } from "../lib/invoices";
import { walletSplit } from "../lib/wallet-split";
import { getSettingBool, getSettingInt } from "../lib/settings";
import { stripeConfigured } from "../lib/stripe";
import { DUNNING_RETRY_ATTEMPTS, emails, sendMail } from "../lib/mailer";
import { appUrl } from "../lib/email-render";
import {
  adoptUnclaimedCards,
  autoRechargeMarker,
  cancelPendingChargeForMarker,
  cardDisplayLabel,
  cardExpiresAt,
  chargeSavedCardOffSession,
  createOutstandingCheckout,
  creditOffSessionCharge,
  forgetMissingPaymentMethod,
  hasChargeableCard,
  renewalCharge,
  renewalChargeMarker,
  type RenewalCharge,
} from "../lib/stripe-cards";

/** Thrown when a compare-and-swap shows someone else already advanced the period. */
class AlreadyRenewedError extends Error {}

const DOMAIN_RENEW_WINDOW_DAYS = 7;
const DAY = 86400_000;

/* ------------------------------------------------------------------ *
 * CARD AUTO-CHARGE + DUNNING
 *
 * A renewal applies wallet credit FIRST and auto-charges the saved card for the
 * remainder — the same split `lib/wallet-split.ts` gives checkout, so a renewal
 * behaves exactly like a purchase and prepaid/referral/refund credit gets drained
 * instead of accumulating as a liability.
 *
 * When the card fails the customer is NOT suspended. The card is retried on days
 * 1, 3 and 5 past expiry, each with its own email, and only once every attempt is
 * spent — plus one clear day after the final notice — does the server pause. The
 * old behaviour sent a customer with a perfectly good card straight to SUSPENDED
 * the moment their wallet emptied, and told them about it with nothing but a bell
 * icon in a portal they had stopped visiting.
 * ------------------------------------------------------------------ */

/**
 * Days past expiry for retry N (1-based): 1, 3, 5 …
 *
 * Derived from DUNNING_RETRY_ATTEMPTS — the same constant `emails.paymentRetryFailed`
 * uses to tell the customer how many attempts remain — so the schedule the worker
 * runs and the number in the email can never drift apart.
 */
const retryDayFor = (retry: number) => 2 * retry - 1;
/** Days past expiry of the LAST automatic retry. */
const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);
/** One clear day between the final-notice email and the suspension it warns about. */
const CARD_SUSPEND_DAY = LAST_RETRY_DAY + 1;
/** `Server.dunningStage` once the attempt on expiry day AND every retry have failed. */
const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;
/**
 * Never schedule a retry sooner than this. The sweep runs every 10 minutes, so a
 * worker that was down for a week would otherwise burn every retry — and every
 * email — in the space of one afternoon.
 */
const MIN_RETRY_GAP_MS = 20 * 3600_000;
/** How soon to re-try after an error that was OUR side, not the customer's. */
const TRANSIENT_RETRY_MS = 60 * 60_000;
/**
 * Hard cap on how far a late-starting or error-delayed sequence may push a
 * suspension past its calendar date. `suspendDueAt` waits for a retry we have
 * PROMISED the customer, and a Stripe outage reschedules that promise hourly
 * forever — without this cap "never suspend mid-sequence" would quietly become
 * "never suspend at all".
 */
const SUSPEND_SLIP_CAP_DAYS = 4;
/** Warn about a saved card this many days before it expires. */
const CARD_EXPIRY_WARN_DAYS = 30;
/** Re-nudge about a still-unreplaced expiring/expired card at most this often. */
const CARD_EXPIRY_RENUDGE_DAYS = 60;
/** Ledger description prefix that identifies an automatic wallet top-up. */
const AUTO_RECHARGE_DESC = "Automatic wallet top-up";
/** Mirrors the floor `saveAutoRecharge` enforces on the customer's own input. */
const AUTO_RECHARGE_MIN_CENTS = 500;

/**
 * Dunning windows, all measured in DAYS PAST EXPIRY.
 *
 * Settings → Billing is the source of truth. Those three fields and the
 * "Auto-suspend overdue accounts" toggle used to be written to the Setting table and
 * read by NOTHING: the worker used env vars that were never set, so an operator who
 * turned suspensions off during an incident saw "Saved." and then watched the sweep
 * knock customer VMs offline ten minutes later.
 *
 * The legacy env vars remain as fallbacks, converted onto the days-past-expiry clock
 * so an operator who had set them keeps the behaviour they configured
 * (NXEON_TERMINATE_DAYS counted forward from the END of grace, and
 * NXEON_WARN_BEFORE_TERMINATE_DAYS counted backwards from termination).
 */
type DunningConfig = {
  /** Days past expiry before an account with no card in play is suspended. */
  graceDays: number;
  /** Days past expiry when the "will be deleted" warning goes out. */
  warnDays: number;
  /** Days past expiry when an unpaid SUSPENDED server is destroyed. */
  terminateDays: number;
  /** Admin kill switch: when false the sweep suspends and terminates nothing. */
  autoSuspend: boolean;
};

const ENV_GRACE_DAYS = Number(process.env.NXEON_GRACE_DAYS ?? 3);
const ENV_TERMINATE_DAYS = process.env.NXEON_TERMINATE_DAYS
  ? ENV_GRACE_DAYS + Number(process.env.NXEON_TERMINATE_DAYS)
  : 14;
const ENV_WARN_DAYS = process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS
  ? ENV_TERMINATE_DAYS - Number(process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS)
  : 7;

async function dunningConfig(): Promise<DunningConfig> {
  const graceDays = Math.max(0, await getSettingInt("dunning_grace_days", ENV_GRACE_DAYS));
  let terminateDays = await getSettingInt("dunning_terminate_days", ENV_TERMINATE_DAYS);
  let warnDays = await getSettingInt("dunning_warn_days", ENV_WARN_DAYS);
  const autoSuspend = await getSettingBool("auto_suspend_enabled", true);

  // Clamp. These are free-text number fields in an admin panel and the action they
  // gate is irreversible — a typo (or a 0) must never be able to destroy a VM on the
  // same day it is suspended, or before the dunning sequence has even finished. The
  // floor includes the slip cap because a card sequence that started late can push
  // the suspension itself out to CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS, and
  // termination must always land AFTER the suspension it follows.
  const latestSuspendDay = Math.max(graceDays, CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS);
  terminateDays = Math.max(terminateDays, latestSuspendDay + 1);
  warnDays = Math.min(Math.max(warnDays, 1), terminateDays - 1);
  return { graceDays, warnDays, terminateDays, autoSuspend };
}

const fmtUsd = (cents: number) => `$${(cents / 100).toFixed(2)}`;
const fmtDay = (d: Date) =>
  d.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" });
const billingUrl = () => `${appUrl()}/dashboard/billing`;

/**
 * Send a transactional email without ever letting the mailer stall billing.
 * `sendMail` already logs every attempt to EmailLog and returns false rather than
 * throwing; this is the belt-and-braces so an SMTP surprise can't abort a sweep
 * halfway through a money decision.
 */
async function mail(to: string, userId: string, tpl: { template?: string; subject: string; html: string }) {
  try {
    await sendMail({ to, subject: tpl.subject, html: tpl.html, template: tpl.template, userId });
  } catch (e) {
    console.error("[billing] email send failed", e);
  }
}

/** In-portal notice. Same never-throw contract as `mail` — bells are not money. */
async function notify(userId: string, title: string, body: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[billing] notification failed", e);
  }
}

/** The renewal queue, and the row shape every card/dunning helper below works on. */
async function dueServers(now: Date) {
  return db.server.findMany({
    where: {
      isFree: false,
      expiresAt: { lt: now },
      status: { in: ["RUNNING", "STOPPED"] },
    },
    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
  });
}
type DueServer = Awaited<ReturnType<typeof dueServers>>[number];

/**
 * Subscription sweep, run periodically by the worker:
 *  - expired + autoRenew, wallet covers it     -> charge wallet, extend the term
 *  - expired + autoRenew, wallet falls short   -> apply the credit, auto-charge the
 *                                                 saved card for the remainder
 *  - card declined                             -> dunning (retry days 1/3/5 + email)
 *  - retries exhausted, or no card past grace  -> queue SUSPEND with unpaid note
 * Free servers (isFree) are never touched.
 */
export async function billingSweep() {
  const now = new Date();
  const cfg = await dunningConfig();
  const prices = {
    ipMonthlyCents: await dedicatedIpMonthlyCents(), // admin setting; 0 = included
    // Per-GB/month price for extra ROOT DISK. Read once per sweep; every server that
    // bought extra storage renews at plan + (extraDiskGB x this) x months, so the
    // upsell keeps billing every cycle rather than being a one-off charge.
    extraDiskPerGbCents: await extraDiskPerGbCents(),
  };

  // Claim any card that was saved at Stripe but never confirmed in the browser,
  // BEFORE the renewal queries read card state — otherwise a customer who closed
  // the tab on Stripe's page gets dunned for a card we simply failed to record.
  try {
    const adopted = await adoptUnclaimedCards(now);
    if (adopted > 0) console.log(`[billing] adopted ${adopted} unconfirmed saved card(s)`);
  } catch (e) {
    console.error("[billing] card adoption error", e);
  }

  // Renewal warnings: notify once when a paid server is within 3 days of expiry
  const soon = new Date(now.getTime() + 3 * 86400_000);
  const upcoming = await db.server.findMany({
    where: {
      isFree: false,
      expiresAt: { gt: now, lt: soon },
      status: { in: ["RUNNING", "STOPPED"] },
    },
    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
  });
  for (const server of upcoming) {
    const warnCents = renewalCharge(server, prices).totalCents;
    // A customer with a card on file needs no warning and no top-up: the renewal
    // applies their wallet credit and auto-charges the card for the remainder.
    // Telling them to "top up to avoid suspension" would raise an alarm about a
    // suspension that is not going to happen.
    if (server.autoRenew && (server.user.balanceCents >= warnCents || hasChargeableCard(server.user))) {
      continue;
    }
    const already = await db.notification.findFirst({
      where: {
        userId: server.userId,
        title: { contains: server.hostname },
        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
        AND: { title: { contains: "renews soon" } },
      },
    });
    if (!already) {
      await db.notification.create({
        data: {
          userId: server.userId,
          title: `${server.hostname} renews soon — action needed`,
          body: server.autoRenew
            ? `Renewal is $${(warnCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
          href: `/dashboard/servers/${server.id}`,
        },
      });
    }
  }
  const due = await dueServers(now);

  for (const server of due) {
    // One unhappy server must never abort the queue behind it. Every money write
    // below is individually guarded (CAS on expiresAt, UNIQUE on the payment intent
    // id, Stripe idempotency key), so continuing past a failure can only ever cost a
    // delayed renewal — never a duplicate charge. Without this, a single row with a
    // wedged Stripe customer would leave every later customer unrenewed AND
    // eventually suspended, for a fault that was entirely ours.
    try {
      await renewDueServer(server, { now, cfg, prices });
    } catch (e) {
      console.error(`[billing] renewal pass failed for ${server.hostname}`, e);
    }
  }

  await terminateOverdue(now, cfg);

  // Card housekeeping: nudge before a saved card expires, and honour the customer's
  // own automatic top-up preference. Both are isolated so a Stripe or SMTP problem
  // can never take the renewal sweep down with it.
  try {
    await cardExpirySweep(now);
  } catch (e) {
    console.error("[billing] card-expiry sweep error", e);
  }
  try {
    await autoRechargeSweep(now);
  } catch (e) {
    console.error("[billing] auto-recharge sweep error", e);
  }

  await domainAutoRenewSweep(now);

  // Poll in-flight inbound transfers on the same cadence as domain renewals —
  // domain upkeep all lives on one timer.
  try {
    await domainTransferInSweep(now);
  } catch (e) {
    console.error("[billing] domain transfer-in sweep error", e);
  }
}

/**
 * One expired server: renew it from wallet + card, or move it along the dunning
 * sequence, or suspend it once every promised attempt is spent.
 */
async function renewDueServer(
  server: DueServer,
  ctx: { now: Date; cfg: DunningConfig; prices: { ipMonthlyCents: number; extraDiskPerGbCents: number } },
) {
  const { now, cfg, prices } = ctx;
  const charge = renewalCharge(server, prices);
  const renewCents = charge.totalCents;
  const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
  const newExpiry = addMonths(base, charge.months);

  await clearStaleDunning(server);

  let renewed = false;
  if (server.autoRenew) {
    // `server.user.balanceCents` came from a snapshot taken before this loop and
    // is stale as soon as the first renewal in this pass debits a wallet, so the
    // SPLIT is computed from a fresh read. It is still never a gate: `debitWallet`
    // re-checks funds atomically and the compare-and-swap on `expiresAt` stops a
    // concurrent renewNow()/second pass charging the same period twice.
    const fresh = await db.user.findUnique({
      where: { id: server.userId },
      select: { balanceCents: true },
    });
    const split = walletSplit({
      dueCents: renewCents,
      balanceCents: fresh?.balanceCents ?? 0,
      useWallet: true,
    });
    const cardInPlay = hasChargeableCard(server.user);

    if (split.cardCents === 0) {
      // Wallet covers the whole renewal — no card involved, no Stripe call.
      const outcome = await commitRenewal({ server, charge, newExpiry });
      renewed = outcome !== "insufficient";
      if (outcome === "renewed") {
        console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
      }
    } else if (cardInPlay) {
      // Only attempt on the scheduled day. Without this gate a 10-minute sweep
      // would burn all three retries — and send all three emails — within half an
      // hour of the first decline.
      //
      // A scheduled time, once set, ALWAYS wins over the attempt counter: that is
      // what makes `retryDunningNow` (fired when a customer saves a new card
      // mid-dunning) actually retry, even at the exhausted stage. Refusing there
      // would suspend a customer whose brand-new card we never once tried.
      const dueForRetry = server.dunningNextAt
        ? now >= server.dunningNextAt
        : server.dunningStage < DUNNING_EXHAUSTED;
      if (dueForRetry) {
        renewed = await attemptCardRenewal({
          server,
          charge,
          cardCents: split.cardCents,
          newExpiry,
          now,
          cfg,
        });
      }
    } else {
      console.log(
        `[billing] ${server.hostname} short by ${fmtUsd(split.cardCents)} and no card on file — grace/suspend applies`,
      );
    }
  }

  if (renewed) {
    // nothing further this pass
  } else {
    const suspendAt = suspendDueAt(server, hasChargeableCard(server.user), cfg);
    if (suspendAt && now >= suspendAt) {
      await suspendUnpaid(server, cfg);
    }
  }
}

/**
 * Drop dunning state that belongs to a period we are no longer collecting for.
 *
 * `renewNow` (lib/actions.ts) advances `expiresAt` without touching the dunning
 * columns, so a customer who paid by hand halfway through a sequence carries a
 * stale `dunningStage` into the NEXT period — and the first decline of that fresh
 * period would arrive as "payment retry 2 declined, 1 attempt remaining", on a
 * compressed schedule, for a period they had never failed once.
 *
 * Every schedule this file writes lands at or after the expiry it was computed
 * from, so a `dunningNextAt` that predates the CURRENT `expiresAt` can only have
 * been written for an older, already-settled period.
 */
async function clearStaleDunning(server: DueServer): Promise<void> {
  if (server.dunningStage === 0 && !server.dunningNextAt && !server.dunningPayUrl) return;
  const belongsToThisPeriod = server.dunningNextAt && server.dunningNextAt >= server.expiresAt!;
  if (belongsToThisPeriod) return;

  await db.server.update({
    where: { id: server.id },
    data: { dunningStage: 0, dunningNextAt: null, dunningPayUrl: null },
  });
  // Keep the in-memory row honest: the rest of this pass reads these fields to
  // decide whether to charge, which email to send and when to suspend.
  server.dunningStage = 0;
  server.dunningNextAt = null;
  server.dunningPayUrl = null;
}

/* ------------------------------------------------------------------ *
 * Renewal commit (wallet) + card auto-charge
 * ------------------------------------------------------------------ */

/**
 * Advance the term and take the money from the wallet, atomically.
 *
 * This is the ONLY place a VPS renewal is granted, whether the wallet was funded
 * by a top-up, a referral credit or the saved card moments ago. One money path
 * means a partial failure can never half-apply a renewal: either the period
 * advances AND the wallet is debited AND the invoice exists, or none of it happened.
 *
 * The compare-and-swap on `expiresAt` is the idempotency guard. A retried sweep, a
 * second worker or a concurrent `renewNow` all read the same snapshot expiry; only
 * the first `updateMany` to match it writes, and every loser rolls back its debit
 * and its invoice with the transaction. Zero rows matched = someone else already
 * renewed this period, which is a success for us, not an error.
 */
async function commitRenewal(opts: {
  server: DueServer;
  charge: RenewalCharge;
  newExpiry: Date;
}): Promise<"renewed" | "insufficient" | "already"> {
  const { server, charge, newExpiry } = opts;
  const renewCents = charge.totalCents;
  const { extraDiskCents, extraDiskMonthlyCents } = charge;
  const periodStart = server.expiresAt!;

  try {
    await db.$transaction(async (tx) => {
      const advanced = await tx.server.updateMany({
        where: { id: server.id, expiresAt: server.expiresAt },
        data: {
          expiresAt: newExpiry,
          // The period is paid, so the collection state that belonged to it dies
          // with it. Leaving a stage behind would hand the NEXT period a
          // half-spent retry budget and the wrong dunning email.
          dunningStage: 0,
          dunningNextAt: null,
          dunningPayUrl: null,
        },
      });
      if (advanced.count === 0) throw new AlreadyRenewedError();
      await debitWallet(tx, server.userId, renewCents);
      await tx.walletTransaction.create({
        data: {
          userId: server.userId,
          amountCents: -renewCents,
          description: `Renewal: ${charge.label} (${server.hostname})`,
        },
      });
      // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
      // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
      // never producing a second invoice for the same period.
      await tx.invoice.create({
        data: invoiceCreateData({
          userId: server.userId,
          description: `Renewal: ${charge.label} (${server.hostname})`,
          status: "PAID",
          period: { start: periodStart, end: newExpiry },
          // Extra disk gets its OWN line so the customer sees exactly what the
          // permanent storage costs each cycle; the lines sum back to renewCents.
          lineItems: [
            {
              description: `${charge.label} — ${server.hostname}`,
              qty: 1,
              unitCents: renewCents - extraDiskCents,
              amountCents: renewCents - extraDiskCents,
            },
            ...(extraDiskCents > 0
              ? [
                  {
                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthlyCents / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: extraDiskCents,
                    amountCents: extraDiskCents,
                  },
                ]
              : []),
          ],
        }),
      });
      await tx.auditLog.create({
        data: { userId: server.userId, action: "billing.renewed", detail: server.id },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
      return "insufficient";
    }
    if (e instanceof AlreadyRenewedError) return "already"; // someone else advanced the period
    throw e;
  }

  // The period is settled. Any 3-D Secure challenge still hanging off it is a
  // loaded gun: anything that later confirms that intent takes a SECOND payment
  // for a period we have already been paid for. Only worth a Stripe round-trip
  // when this server was actually mid-dunning.
  if (server.dunningStage > 0 || server.dunningPayUrl) {
    await cancelPendingChargeForMarker(
      server.user.stripeCustomerId,
      renewalChargeMarker(server.id, periodStart),
    );
  }
  return "renewed";
}

/**
 * Charge the saved card for the wallet shortfall, then renew.
 *
 * The card NEVER pays the invoice directly. It credits the wallet with exactly
 * what Stripe captured, and `commitRenewal` then debits the FULL renewal from the
 * wallet — identical to how checkout splits a purchase. That ordering is what
 * makes a crash safe in both directions: money captured but not yet applied sits
 * in the customer's wallet as credit (visible, spendable, refundable), and a
 * renewal can never be granted without a matching debit.
 *
 * TWO idempotency guards ride on every attempt:
 *  - `marker` (server + period) — a permanent pre-flight lookup at Stripe for a
 *    live PaymentIntent for this exact period, so a crash between "Stripe captured"
 *    and "we recorded it" replays instead of charging again.
 *  - `idempotencyKey` (server + period + attempt + amount) — Stripe replays an
 *    identical request for 24h, which covers two overlapping sweeps of the SAME
 *    scheduled attempt. The attempt and amount are in the key because a genuine
 *    day-3 retry, or a retry for a different remainder after the wallet moved, is a
 *    deliberately NEW charge; reusing the key there would make Stripe reject it.
 *
 * And the credit itself is guarded by the UNIQUE index on
 * `WalletTransaction.stripePaymentIntentId`, so even a replayed capture credits once.
 *
 * @returns true when the term was actually extended.
 */
async function attemptCardRenewal(opts: {
  server: DueServer;
  charge: RenewalCharge;
  cardCents: number;
  newExpiry: Date;
  now: Date;
  cfg: DunningConfig;
}): Promise<boolean> {
  const { server, charge, cardCents, newExpiry, now, cfg } = opts;
  const user = server.user;
  const periodStart = server.expiresAt!;
  const marker = renewalChargeMarker(server.id, periodStart);
  const idempotencyKey = `nxeon_renew_${server.id}_${periodStart.getTime()}_a${server.dunningStage}_${cardCents}`;
  const cardLabel = cardDisplayLabel(user) ?? "your saved card";

  const result = await chargeSavedCardOffSession({
    user,
    amountCents: cardCents,
    description: `Renewal: ${charge.label} (${server.hostname})`,
    marker,
    idempotencyKey,
    metadata: {
      nxeonServerId: server.id,
      nxeonPeriodStart: periodStart.toISOString(),
      nxeonKind: "renewal",
    },
  });

  if (result.ok) {
    // Exactly what Stripe took, not what we asked for — a replayed intent can carry
    // an older amount and the ledger must match the bank, not our intent.
    const credited = await creditOffSessionCharge({
      userId: server.userId,
      amountCents: result.amountCents,
      description: `Card payment for ${server.hostname} renewal (${cardLabel})`,
      paymentIntentId: result.paymentIntentId,
      // No invoice for the card leg: `commitRenewal` issues ONE paid invoice for
      // the whole renewal, and a second document for the card portion would
      // double-count the same revenue.
    });
    const outcome = await commitRenewal({ server, charge, newExpiry });

    // The receipt is tied to the CREDIT, not the renewal: `creditOffSessionCharge`
    // returns false on the P2002 that means "already credited", so a replayed
    // capture cannot email the same customer a second receipt for one charge.
    if (credited) {
      await mail(
        user.email,
        user.id,
        emails.paymentReceipt(
          fmtUsd(result.amountCents),
          `${charge.label} — ${server.hostname}`,
          user.cardLast4 ?? "",
        ),
      );
    }

    if (outcome === "insufficient") {
      // The card paid, the wallet was credited, and the debit STILL failed — the
      // customer spent the credit between our split read and the transaction. The
      // money is not lost, it is sitting in their wallet; re-run shortly rather
      // than charging again (the marker replays this same capture, so the next
      // pass cannot take a second payment) and do NOT count it as a dunning
      // failure, because nothing about their card went wrong.
      console.error(
        `[billing] ${server.hostname}: card captured ${fmtUsd(result.amountCents)} but the wallet debit fell short — retrying shortly`,
      );
      await db.server.update({
        where: { id: server.id },
        data: { dunningNextAt: new Date(now.getTime() + TRANSIENT_RETRY_MS) },
      });
      return false;
    }
    if (outcome === "renewed") {
      console.log(
        `[billing] renewed ${server.hostname} until ${newExpiry.toISOString()} (card ${fmtUsd(result.amountCents)}${result.replayed ? ", replayed" : ""})`,
      );
    }
    return true;
  }

  if (result.kind === "transient") {
    // Our side or Stripe's side wobbled. Never a dunning event: a misclassified
    // transient costs a delayed renewal, a misclassified decline costs a paid-up
    // customer their server. The attempt counter is untouched.
    console.warn(`[billing] transient charge error for ${server.hostname}: ${result.message}`);
    await db.server.update({
      where: { id: server.id },
      data: { dunningNextAt: new Date(now.getTime() + TRANSIENT_RETRY_MS) },
    });
    return false;
  }

  if (result.kind === "unavailable") {
    // `hasChargeableCard` already proved Stripe is configured and both ids are
    // present, and `walletSplit` keeps the amount above Stripe's floor — so the
    // only way here is `resource_missing`: the payment method no longer exists at
    // Stripe. Not a decline; there is nothing to retry until a new card is saved.
    // Clearing the columns matters twice over: the portal stops claiming a card is
    // on file, and `suspendDueAt` stops granting card-customer runway to an account
    // that has no card at all.
    console.warn(`[billing] saved card unusable for ${server.hostname}: ${result.message}`);
    await forgetMissingPaymentMethod(server.userId).catch((e) =>
      console.error("[billing] could not clear missing payment method", e),
    );
    await db.server.update({ where: { id: server.id }, data: { dunningNextAt: null } });
    await notify(
      server.userId,
      "Your saved card is no longer available",
      `We couldn't use the card saved for ${server.hostname} — your bank or Stripe no longer recognises it. Add a card to keep your services renewing automatically.`,
      "/dashboard/billing",
    );
    return false;
  }

  if (result.kind === "requires_action") {
    // 3-D Secure. Off-session there is no browser to satisfy the challenge, so the
    // answer is a hosted Checkout link: the customer completes the bank step on
    // Stripe's own page, the money lands as wallet credit and the next sweep
    // renews from the wallet. This is NOT a decline — nothing about the card is
    // wrong — so it must never consume a retry, or a customer who simply hasn't
    // opened their email yet would be dunned toward suspension for their bank's
    // security policy.
    let payUrl = server.dunningPayUrl;
    if (!payUrl) {
      payUrl = await createOutstandingCheckout({
        user,
        amountCents: cardCents,
        hostname: server.hostname,
        serverId: server.id,
      });
      if (payUrl) {
        await db.server.update({ where: { id: server.id }, data: { dunningPayUrl: payUrl } });
        await mail(
          user.email,
          user.id,
          emails.paymentActionRequired(server.hostname, fmtUsd(cardCents), payUrl),
        );
        await notify(
          server.userId,
          `${server.hostname} — your bank needs to confirm the payment`,
          `Your card issuer asked for an extra verification step for ${fmtUsd(cardCents)}. Confirming it finishes the renewal. Nothing is suspended.`,
          `/dashboard/servers/${server.id}`,
        );
      }
    }
    // Re-check daily rather than hourly: the challenge does not move, and the same
    // link is already in their inbox. `dunningPayUrl` being set is what stops the
    // email repeating for this period; `clearStaleDunning`/`commitRenewal` clear it.
    await db.server.update({
      where: { id: server.id },
      data: { dunningNextAt: new Date(now.getTime() + MIN_RETRY_GAP_MS) },
    });
    console.log(`[billing] ${server.hostname} awaiting 3-D Secure confirmation for ${fmtUsd(cardCents)}`);
    return false;
  }

  // Hard decline — the issuer said no. This is the only outcome that spends an
  // attempt and moves the customer along the dunning sequence.
  await recordDeclinedAttempt({ server, cardCents, now, cfg, reason: result.message });
  return false;
}

/**
 * Book a real decline: advance `dunningStage`, schedule the next attempt from the
 * day-1/3/5 table and send the email that matches where the customer now is.
 *
 * The stage is CLAMPED at DUNNING_EXHAUSTED so a re-armed attempt (a new card
 * saved after the sequence ran out) that also fails cannot send a second final
 * notice or push the customer past the end of a schedule that has no more entries.
 */
async function recordDeclinedAttempt(opts: {
  server: DueServer;
  cardCents: number;
  now: Date;
  cfg: DunningConfig;
  reason: string;
}): Promise<void> {
  const { server, cardCents, now, cfg, reason } = opts;
  const prevStage = server.dunningStage;
  const newStage = Math.min(prevStage + 1, DUNNING_EXHAUSTED);
  const amount = fmtUsd(cardCents);
  const last4 = server.user.cardLast4 ?? "";
  // The date the customer is told about must be the date the sweep will actually
  // act on, so both come from `suspendDueAt`.
  const suspendAt = suspendDueAt(server, true, cfg) ?? new Date(server.expiresAt!.getTime() + CARD_SUSPEND_DAY * DAY);

  console.warn(`[billing] card declined for ${server.hostname} (attempt ${newStage}): ${reason}`);

  if (prevStage >= DUNNING_EXHAUSTED) {
    // Already out of attempts; this was an extra try we granted (usually because a
    // new card was saved). Keep trying about once a day, silently — the customer
    // has already had the final notice and another copy of it would just be noise.
    await db.server.update({
      where: { id: server.id },
      data: { dunningNextAt: new Date(now.getTime() + MIN_RETRY_GAP_MS) },
    });
    return;
  }

  const nextAt = nextRetryAt(server.expiresAt!, newStage, now) ?? suspendAt;
  await db.server.update({
    where: { id: server.id },
    data: { dunningStage: newStage, dunningNextAt: nextAt },
  });
  server.dunningStage = newStage;
  server.dunningNextAt = nextAt;

  await db.auditLog
    .create({
      data: {
        userId: server.userId,
        action: "billing.card_declined",
        detail: `${server.id}: attempt ${newStage} for ${amount} — ${reason.slice(0, 180)}`,
      },
    })
    .catch(() => {
      /* audit is bookkeeping; never let it break collection */
    });

  if (newStage === 1) {
    // FIRST failure of the period. Five-positional-string overload — the object
    // form is the legacy catalog shape used by the admin template previewer.
    await mail(
      server.user.email,
      server.userId,
      emails.paymentFailed(server.hostname, amount, last4, fmtDay(nextAt), billingUrl()),
    );
  } else if (newStage < DUNNING_EXHAUSTED) {
    // `attempt` counts RETRIES (the expiry-day attempt is attempt 0), which is what
    // `emails.paymentRetryFailed` subtracts from DUNNING_RETRY_ATTEMPTS to tell the
    // customer how many tries are left.
    await mail(
      server.user.email,
      server.userId,
      emails.paymentRetryFailed(server.hostname, amount, newStage - 1, fmtDay(suspendAt), billingUrl()),
    );
  } else {
    await mail(
      server.user.email,
      server.userId,
      emails.paymentFinalNotice(server.hostname, amount, billingUrl()),
    );
  }

  await notify(
    server.userId,
    `${server.hostname} — card payment ${newStage >= DUNNING_EXHAUSTED ? "failed, final notice" : "declined"}`,
    newStage >= DUNNING_EXHAUSTED
      ? `We've run out of automatic attempts for ${amount}. ${server.hostname} is still running — settle the balance to keep it that way.`
      : `We couldn't charge ${amount} to your card. Nothing is suspended; we'll try again on ${fmtDay(nextAt)}.`,
    `/dashboard/servers/${server.id}`,
  );
}

/**
 * When the Nth failed attempt should be followed by another one.
 *
 * Floored at MIN_RETRY_GAP_MS so a worker that has been down for a week does not
 * discover four overdue slots at once and fire the entire sequence — three charges
 * and three emails — inside a single afternoon.
 */
function nextRetryAt(expiresAt: Date, failures: number, now: Date): Date | null {
  if (failures >= DUNNING_EXHAUSTED) return null;
  const scheduled = new Date(expiresAt.getTime() + retryDayFor(failures) * DAY);
  const floor = new Date(now.getTime() + MIN_RETRY_GAP_MS);
  return scheduled > floor ? scheduled : floor;
}

/* ------------------------------------------------------------------ *
 * Suspension
 * ------------------------------------------------------------------ */

/**
 * When this overdue server may be paused — null means never (auto-suspend is off).
 *
 * With a card in play the deadline is CARD_SUSPEND_DAY past expiry: one clear day
 * after the final-notice email, so the customer always gets a full day with the
 * warning in hand before anything stops. Without a card there is nothing to wait
 * for beyond the configured grace period.
 *
 * The deadline also never lands BEFORE an attempt we have promised. A worker that
 * was down for the first five days starts the sequence late; suspending on the
 * calendar alone would then pause a server minutes after emailing "we'll try your
 * card again on <date>" — the exact broken promise this whole feature exists to
 * stop. That slip is capped (see SUSPEND_SLIP_CAP_DAYS) and only applies while
 * attempts actually remain, so a permanently failing Stripe cannot defer
 * suspension forever.
 */
function suspendDueAt(
  server: { expiresAt: Date | null; dunningStage: number; dunningNextAt: Date | null },
  hasCard: boolean,
  cfg: DunningConfig,
): Date | null {
  if (!cfg.autoSuspend || !server.expiresAt) return null;
  const days = hasCard ? Math.max(cfg.graceDays, CARD_SUSPEND_DAY) : cfg.graceDays;
  const at = new Date(server.expiresAt.getTime() + days * DAY);
  if (!hasCard || server.dunningStage >= DUNNING_EXHAUSTED || !server.dunningNextAt) return at;
  if (server.dunningNextAt <= at) return at;
  const cap = new Date(server.expiresAt.getTime() + (days + SUSPEND_SLIP_CAP_DAYS) * DAY);
  return server.dunningNextAt < cap ? server.dunningNextAt : cap;
}

/**
 * Pause an unpaid server: mark it, queue the SUSPEND job, tell the customer.
 *
 * `suspendReason: "UNPAID"` is load-bearing, not a label. It is what scopes
 * `terminateOverdue` (below) and the auto-unsuspend in `renewNow` to billing
 * suspensions only, so an abuse or admin suspension can never be deleted by the
 * overdue sweep nor lifted by a customer paying a bill.
 */
async function suspendUnpaid(server: DueServer, cfg: DunningConfig): Promise<void> {
  if (!cfg.autoSuspend) return; // admin kill switch — belt and braces
  // Never queue a second SUSPEND behind one that is already queued or running:
  // duplicate jobs against one VM are how a suspend/unsuspend race leaves a paid-up
  // customer offline.
  const pending = await db.job.count({
    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending !== 0) return;

  await db.server.update({
    where: { id: server.id },
    data: {
      suspendedNote: "unpaid — renew from your billing page to restore access",
      // Only an UNPAID suspension may be terminated by the overdue sweep or
      // lifted automatically by paying. See Server.suspendReason.
      suspendReason: "UNPAID",
    },
  });
  await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
  await db.auditLog.create({
    data: { userId: server.userId, action: "billing.suspended_unpaid", detail: server.id },
  });
  await db.notification.create({
    data: {
      userId: server.userId,
      title: `${server.hostname} suspended — payment overdue`,
      body: "Pay from the server page to restore access instantly.",
      href: `/dashboard/servers/${server.id}`,
    },
  });
  console.log(`[billing] suspending unpaid ${server.hostname}`);
}

/* ------------------------------------------------------------------ *
 * Card housekeeping
 * ------------------------------------------------------------------ */

/**
 * Warn before a saved card expires.
 *
 * A card that lapses turns a customer who has done nothing wrong into a dunning
 * case: the renewal declines, the sequence starts, and the first they hear of it
 * is "your card was declined". Thirty days' notice costs one email and prevents
 * the whole sequence.
 *
 * `User.cardExpiryNotifiedAt` is both the sent-marker and the re-nudge clock, and
 * `persistCard` (lib/stripe-cards.ts) resets it to null whenever a card is saved —
 * so replacing an expiring card silently re-arms the warning for the new one
 * instead of suppressing it forever.
 */
async function cardExpirySweep(now: Date): Promise<void> {
  if (!stripeConfigured()) return;
  const horizon = new Date(now.getTime() + CARD_EXPIRY_WARN_DAYS * DAY);
  const renudgeBefore = new Date(now.getTime() - CARD_EXPIRY_RENUDGE_DAYS * DAY);

  const users = await db.user.findMany({
    where: {
      suspended: false,
      stripePaymentMethodId: { not: null },
      cardExpMonth: { not: null },
      cardExpYear: { not: null },
      OR: [{ cardExpiryNotifiedAt: null }, { cardExpiryNotifiedAt: { lt: renudgeBefore } }],
    },
    select: {
      id: true,
      email: true,
      cardBrand: true,
      cardLast4: true,
      cardExpMonth: true,
      cardExpYear: true,
    },
  });

  for (const user of users) {
    // A card works THROUGH the last day of its expiry month; `cardExpiresAt`
    // returns the first instant it stops working. Doing this arithmetic inline
    // once got it off by a month, which either nags 30 days early or warns after
    // the renewal has already declined.
    const expiresAt = cardExpiresAt(user.cardExpMonth!, user.cardExpYear!);
    if (expiresAt > horizon) continue;

    await mail(
      user.email,
      user.id,
      emails.cardExpiringSoon(user.cardLast4 ?? "", user.cardExpMonth!, user.cardExpYear!, billingUrl()),
    );
    // Written whether or not SMTP accepted it: a broken mail server must not turn
    // this sweep into a mailer loop that retries the same address every 10 minutes.
    await db.user.update({ where: { id: user.id }, data: { cardExpiryNotifiedAt: now } });
    await notify(
      user.id,
      expiresAt <= now ? "Your saved card has expired" : "Your saved card expires soon",
      `${cardDisplayLabel(user) ?? "The card on your account"} ${expiresAt <= now ? "can no longer be charged" : "expires soon"}. Save an up-to-date card so your renewals keep going through.`,
      "/dashboard/billing",
    );
    console.log(`[billing] card-expiry notice sent to ${user.email}`);
  }
}

/**
 * Honour the customer's own "keep my wallet topped up" preference.
 *
 * This is opt-in and customer-configured (`autoRechargeEnabled` /
 * `autoRechargeThresholdCents` / `autoRechargeAmountCents`), and it is the only
 * charge in this file that is NOT tied to a renewal — so unlike the renewal leg it
 * DOES get its own invoice, because it is the whole payment rather than one part
 * of a larger one.
 *
 * `autoRechargeMarker` is scoped to the account and the CALENDAR DAY, which caps
 * this at one top-up per account per day no matter how many times the sweep runs
 * or how fast the customer spends. Combined with the UNIQUE index on
 * `WalletTransaction.stripePaymentIntentId`, a replayed capture credits once and
 * emails once.
 */
async function autoRechargeSweep(now: Date): Promise<void> {
  if (!stripeConfigured()) return;
  const users = await db.user.findMany({
    where: {
      autoRechargeEnabled: true,
      suspended: false,
      stripeCustomerId: { not: null },
      stripePaymentMethodId: { not: null },
    },
  });

  for (const user of users) {
    const threshold = user.autoRechargeThresholdCents ?? 0;
    const amount = user.autoRechargeAmountCents ?? 0;
    // A threshold of 0 means "never", and an amount below the floor the customer's
    // own settings form enforces is a stale/hand-edited row — charging on either
    // would be taking money the customer did not ask for.
    if (threshold <= 0 || amount < AUTO_RECHARGE_MIN_CENTS) continue;
    if (user.balanceCents >= threshold) continue;

    const day = now.toISOString().slice(0, 10);
    const marker = autoRechargeMarker(user.id, now);
    let result;
    try {
      result = await chargeSavedCardOffSession({
        user,
        amountCents: amount,
        description: `${AUTO_RECHARGE_DESC} — Nxeon wallet`,
        marker,
        idempotencyKey: `nxeon_autorecharge_${user.id}_${day}_${amount}`,
        metadata: { nxeonKind: "auto_recharge" },
      });
    } catch (e) {
      // One wedged account must not stop the others from topping up.
      console.error(`[billing] auto-recharge error for ${user.email}`, e);
      continue;
    }

    if (result.ok) {
      const credited = await creditOffSessionCharge({
        userId: user.id,
        amountCents: result.amountCents,
        description: `${AUTO_RECHARGE_DESC} (${cardDisplayLabel(user) ?? "saved card"})`,
        paymentIntentId: result.paymentIntentId,
        // This charge IS the whole payment, so it gets its own PAID invoice — in
        // the same guarded write, so the invoice cannot outlive a rolled-back credit.
        invoiceDescription: AUTO_RECHARGE_DESC,
      });
      if (!credited) continue; // already credited today — nothing new to announce
      await mail(
        user.email,
        user.id,
        emails.paymentReceipt(fmtUsd(result.amountCents), AUTO_RECHARGE_DESC, user.cardLast4 ?? ""),
      );
      await notify(
        user.id,
        `Wallet topped up ${fmtUsd(result.amountCents)}`,
        `Your balance had dropped below ${fmtUsd(threshold)}, so we topped it up automatically using your saved card.`,
        "/dashboard/billing",
      );
      console.log(`[billing] auto-recharged ${user.email} by ${fmtUsd(result.amountCents)}`);
      continue;
    }

    if (result.kind === "unavailable") {
      // The method is gone at Stripe. Clear it so the portal stops offering a card
      // that cannot be charged (see the same branch in attemptCardRenewal).
      await forgetMissingPaymentMethod(user.id).catch(() => {
        /* best-effort */
      });
      continue;
    }
    if (result.kind !== "declined") continue; // transient / 3-D Secure: try again later, silently

    // A declined top-up must NOT touch any server's dunning state — nothing is
    // overdue, the customer simply asked us to keep a float. Tell them once a day
    // and leave it there.
    const already = await db.notification.findFirst({
      where: {
        userId: user.id,
        title: { contains: "Automatic top-up" },
        createdAt: { gt: new Date(now.getTime() - DAY) },
      },
    });
    if (!already) {
      await notify(
        user.id,
        "Automatic top-up declined",
        `We couldn't charge ${fmtUsd(amount)} to your saved card for an automatic wallet top-up. Your services are unaffected — update your card when you get a moment.`,
        "/dashboard/billing",
      );
    }
  }
}

/* ------------------------------------------------------------------ *
 * Inbound domain transfers (transfer-in)
 * ------------------------------------------------------------------ */

/** Remind the customer to approve the confirmation email at most this often. */
const TRANSFER_NUDGE_DAYS = 3;

/**
 * Poll every TRANSFER_PENDING domain and move it to its real state.
 *
 * An ICANN transfer takes ~5-7 days and only completes once the owner approves
 * an email from the LOSING registrar, so this is a slow poll, not a spinner:
 *   completed -> ACTIVE, dates taken from the registrar, auth code scrubbed
 *   failed    -> TRANSFER_FAILED, wallet credited back, reason recorded
 *   pending   -> raw registrar status refreshed for display, gentle nudge
 *
 * Every mutation goes through the shared CAS-guarded settle helpers, so a
 * re-run, two workers racing, or a customer cancelling at the same moment can
 * never credit the same transfer twice.
 */
async function domainTransferInSweep(now: Date) {
  if (!transfersAvailable()) return; // registrar not configured — skip silently

  const pending = await db.domain.findMany({
    where: { status: "TRANSFER_PENDING", isTransferIn: true },
  });

  for (const domain of pending) {
    try {
      const info = await getTransfer(domain.name, domain.transferStartedAt);

      // No transfer on record. Normal once a transfer settles and drops off the
      // registrar's list — resolve it against the account rather than guessing.
      if (!info) {
        const owned = await domainInfo(domain.name).catch(() => null);
        if (owned?.expires) {
          await completeTransferIn(domain, "completed", owned);
          continue;
        }
        const startedAt = domain.transferStartedAt ?? domain.createdAt;
        const ageDays = (now.getTime() - startedAt.getTime()) / DAY;
        if (ageDays > TRANSFER_STALE_DAYS) {
          await failTransferIn(
            domain,
            null,
            `The registrar has no record of this transfer after ${Math.round(ageDays)} days. It did not complete.`
          );
        }
        continue;
      }

      const outcome = transferOutcome(info.status);

      if (outcome === "completed") {
        const owned = await domainInfo(domain.name).catch(() => null);
        await completeTransferIn(domain, info.status, owned);
        continue;
      }

      if (outcome === "failed") {
        await failTransferIn(domain, info.status, transferStatusLabel(info.status));
        continue;
      }

      // Still in flight — keep the displayed registrar status fresh.
      if (info.status !== domain.transferStatus || (info.email && info.email !== domain.transferEmail)) {
        await db.domain.update({
          where: { id: domain.id },
          data: { transferStatus: info.status, ...(info.email ? { transferEmail: info.email } : {}) },
        });
      }
      await nudgeTransferApproval(domain, info.status, info.email, now);
    } catch (e) {
      // One unhappy domain must never abort the sweep. Nothing is settled and
      // no money moves on an unknown state — we simply try again next pass.
      console.error(`[billing] transfer-in poll failed for ${domain.name}`, e);
    }
  }
}

async function completeTransferIn(
  domain: { id: string; name: string; userId: string },
  rawStatus: string,
  owned: { expires?: Date; created?: Date } | null
) {
  const expiresAt = owned?.expires ?? new Date(Date.now() + TRANSFER_TERM_YEARS * 365 * DAY);
  const settled = await settleCompletedTransferIn({
    domainId: domain.id,
    transferStatus: rawStatus,
    registeredAt: owned?.created ?? new Date(),
    expiresAt,
  });
  if (!settled) return;

  await db.auditLog.create({
    data: { userId: domain.userId, action: "domain.transfer_in.completed", detail: domain.name },
  });
  await db.notification.create({
    data: {
      userId: domain.userId,
      title: `${domain.name} transferred in successfully`,
      body: `It's now managed here and expires ${expiresAt.toISOString().slice(0, 10)} — the transfer added a year. DNS and auto-renew are ready to set up.`,
      href: `/dashboard/domains/${domain.id}`,
    },
  });
  console.log(`[billing] transfer-in completed for ${domain.name}`);
}

async function failTransferIn(
  domain: { id: string; name: string; userId: string; priceCents: number },
  rawStatus: string | null,
  reason: string
) {
  const settled = await settleFailedTransferIn({
    domainId: domain.id,
    transferStatus: rawStatus,
    reason,
  });
  if (!settled) return;

  await db.notification.create({
    data: {
      userId: domain.userId,
      title: `${domain.name} transfer did not complete`,
      body: `${reason} We've credited $${(domain.priceCents / 100).toFixed(2)} back to your wallet. The most common cause is the confirmation email from your old registrar not being approved in time — you can start a new transfer whenever you're ready.`,
      href: `/dashboard/domains/${domain.id}`,
    },
  });
  console.log(`[billing] transfer-in failed for ${domain.name}: ${reason}`);
}

/**
 * Nothing completes until the customer approves the losing registrar's email,
 * and that email is easy to miss. Nudge once every few days while we're waiting
 * — deduped on the notification log, same as the other billing reminders.
 */
async function nudgeTransferApproval(
  domain: { id: string; name: string; userId: string; transferStartedAt: Date | null; createdAt: Date },
  rawStatus: string,
  email: string | null,
  now: Date
) {
  const startedAt = domain.transferStartedAt ?? domain.createdAt;
  if (now.getTime() - startedAt.getTime() < 2 * DAY) return; // give them room first

  const already = await db.notification.findFirst({
    where: {
      userId: domain.userId,
      title: { contains: domain.name },
      AND: { title: { contains: "still waiting" } },
      createdAt: { gt: new Date(now.getTime() - TRANSFER_NUDGE_DAYS * DAY) },
    },
  });
  if (already) return;

  await db.notification.create({
    data: {
      userId: domain.userId,
      title: `${domain.name} transfer is still waiting`,
      body:
        `Registrar status: ${transferStatusLabel(rawStatus)}. ` +
        (email ? `Check ${email} ` : "Check the inbox for the domain's registered contact ") +
        `for the confirmation email from your CURRENT registrar and approve it. Transfers normally take 5–7 days and expire if the approval never arrives.`,
      href: `/dashboard/domains/${domain.id}`,
    },
  });
}

/**
 * Terminate servers that have been SUSPENDED (unpaid) past the termination window,
 * reclaiming disk + dedicated IP. Warns the customer before the final deletion.
 * A payment before this point unsuspends the server, so this only ever hits
 * genuinely abandoned accounts. Free servers are never terminated.
 *
 * Both windows are measured in DAYS PAST EXPIRY and come from Settings → Billing
 * (`dunningConfig`), clamped so termination can never land on or before the day the
 * server was suspended — including the extra days a late-starting card dunning
 * sequence is allowed to slip.
 */
async function terminateOverdue(now: Date, cfg: DunningConfig) {
  // The admin kill switch covers deletion too. An operator who turns auto-suspend
  // off during an incident means "stop taking servers away from customers", and
  // the irreversible half of that is the half that must obey first.
  if (!cfg.autoSuspend) return;

  // ONLY unpaid suspensions. This used to select on `status: "SUSPENDED"` alone,
  // while the renewal sweep EXCLUDES suspended servers — so an admin suspending a
  // paid-up customer pending an abuse investigation meant that customer was never
  // charged and never warned, their term quietly lapsed, and 13 days later this
  // function destroyed their VM and all its data with a "prolonged non-payment"
  // notice they had never been given the chance to act on. They had auto-renew on
  // and money in their wallet the entire time.
  //
  // Legacy rows suspended before `suspendReason` existed have it null; those are
  // deliberately excluded too. Failing to delete is always the safer error here —
  // an un-terminated server costs disk, a wrongly-terminated one is unrecoverable.
  const suspended = await db.server.findMany({
    where: {
      isFree: false,
      status: "SUSPENDED",
      suspendReason: "UNPAID",
      expiresAt: { not: null },
    },
  });
  for (const server of suspended) {
    const terminateAt = server.expiresAt!.getTime() + cfg.terminateDays * DAY;
    const warnAt = server.expiresAt!.getTime() + cfg.warnDays * DAY;

    if (now.getTime() >= terminateAt) {
      const pending = await db.job.count({
        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
      });
      if (pending > 0) continue;
      await db.server.update({ where: { id: server.id }, data: { status: "DELETING" } });
      await db.job.create({ data: { type: "DELETE", serverId: server.id } });
      await db.auditLog.create({
        data: { userId: server.userId, action: "billing.terminated_unpaid", detail: server.id },
      });
      await db.notification.create({
        data: {
          userId: server.userId,
          title: `${server.hostname} was permanently deleted`,
          body: "Your server and its data were removed after prolonged non-payment.",
        },
      });
      console.log(`[billing] terminating abandoned ${server.hostname}`);
    } else if (now.getTime() >= warnAt) {
      const already = await db.notification.findFirst({
        where: {
          userId: server.userId,
          title: { contains: server.hostname },
          AND: { title: { contains: "will be deleted" } },
          createdAt: { gt: new Date(now.getTime() - 2 * DAY) },
        },
      });
      if (!already) {
        await db.notification.create({
          data: {
            userId: server.userId,
            title: `${server.hostname} will be deleted soon`,
            body: `This suspended server and all its data will be permanently deleted on ${new Date(terminateAt).toISOString().slice(0, 10)} unless you pay. Restore it now from your billing page.`,
            href: `/dashboard/servers/${server.id}`,
          },
        });
      }
    }
  }
}

/**
 * Auto-renew domains expiring within 7 days when the owner opted in and has
 * the funds. Charges the wallet, extends expiry +365d and notifies the owner.
 * Failures (registrar error, misconfig) notify the owner to renew manually and
 * never charge the wallet.
 */
async function domainAutoRenewSweep(now: Date) {
  if (!registrarConfigured()) return; // registrar not configured — skip silently

  const cutoff = new Date(now.getTime() + DOMAIN_RENEW_WINDOW_DAYS * 86400_000);
  const domains = await db.domain.findMany({
    where: {
      autoRenew: true,
      status: "ACTIVE",
      expiresAt: { not: null, lt: cutoff },
    },
    include: { user: true },
  });

  for (const domain of domains) {
    if (!domain.expiresAt) continue;
    const dTerm = domainTerm(domain.termYears);
    const dRenewCents = domainTermPriceCents(domain.priceCents, dTerm.years); // retail (customer)
    const dRegistrarCost = (domain.costCents || domain.priceCents) * dTerm.years; // cost (registrar)
    if (domain.user.balanceCents < dRenewCents) {
      const already = await db.notification.findFirst({
        where: {
          userId: domain.userId,
          title: { contains: domain.name },
          AND: { title: { contains: "auto-renew failed" } },
          createdAt: { gt: new Date(now.getTime() - 3 * 86400_000) },
        },
      });
      if (!already) {
        await db.notification.create({
          data: {
            userId: domain.userId,
            title: `${domain.name} auto-renew failed — top up to renew`,
            body: `Renewal is $${(dRenewCents / 100).toFixed(2)} (${dTerm.label}) but your balance is $${(domain.user.balanceCents / 100).toFixed(2)}. Top up and renew manually before ${domain.expiresAt.toISOString().slice(0, 10)}.`,
            href: `/dashboard/domains`,
          },
        });
      }
      continue;
    }

    try {
      await renewDomain(domain.name, dTerm.years, dRegistrarCost);
    } catch (e) {
      console.error(`[billing] domain auto-renew failed for ${domain.name}`, e);
      await db.notification.create({
        data: {
          userId: domain.userId,
          title: `${domain.name} auto-renew failed — please renew manually`,
          body: `We couldn't renew ${domain.name} automatically: ${String((e as any)?.message ?? e).slice(0, 200)}. Renew it manually from your domains page.`,
          href: `/dashboard/domains`,
        },
      });
      continue;
    }

    const newExpiry = new Date(domain.expiresAt.getTime() + dTerm.years * 365 * 86400_000);
    // The registrar renewal already succeeded above, so the cost is committed.
    // Charge with the guarded debit (the loop's snapshot balance is stale), and
    // CAS the expiry so a concurrent manual renew can't be charged twice. If the
    // wallet can't cover it we must STILL record the renewal we paid for — flag it
    // as uncharged for ops rather than silently eating it or renewing twice later.
    try {
      await db.$transaction(async (tx) => {
        const advanced = await tx.domain.updateMany({
          where: { id: domain.id, expiresAt: domain.expiresAt },
          data: { expiresAt: newExpiry },
        });
        if (advanced.count === 0) throw new AlreadyRenewedError();
        await debitWallet(tx, domain.userId, dRenewCents);
        await tx.walletTransaction.create({
          data: {
            userId: domain.userId,
            amountCents: -dRenewCents,
            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
          },
        });
        // PAID invoice on the successfully-charged path only (the uncharged
        // InsufficientBalance branch below deliberately makes no invoice). Inside
        // the CAS-guarded tx, so a repeated sweep rolls it back with the debit.
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: domain.userId,
            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
            status: "PAID",
            period: { start: domain.expiresAt, end: newExpiry },
            lineItems: [
              { description: `Domain renewal — ${domain.name} (${dTerm.label})`, qty: 1, unitCents: dRenewCents, amountCents: dRenewCents },
            ],
          }),
        });
        await tx.auditLog.create({
          data: { userId: domain.userId, action: "domain.auto_renewed", detail: domain.name },
        });
      });
    } catch (e) {
      if (e instanceof AlreadyRenewedError) {
        continue; // someone already advanced this period
      }
      if (e instanceof InsufficientBalanceError) {
        await db.domain.update({ where: { id: domain.id }, data: { expiresAt: newExpiry } });
        await db.auditLog.create({
          data: {
            userId: domain.userId,
            action: "domain.renew.uncharged",
            detail: `${domain.name}: renewed at registrar but wallet could not be charged ${dRenewCents}c — collect manually`,
          },
        });
        console.error(`[billing] UNCHARGED domain renewal for ${domain.name} (insufficient balance)`);
        continue;
      }
      throw e;
    }
    await db.notification.create({
      data: {
        userId: domain.userId,
        title: `${domain.name} renewed automatically`,
        body: `Charged $${(domain.priceCents / 100).toFixed(2)}. New expiry: ${newExpiry.toISOString().slice(0, 10)}.`,
        href: `/dashboard/domains`,
      },
    });
    console.log(`[billing] auto-renewed domain ${domain.name} until ${newExpiry.toISOString()}`);
  }
}

