450	async function commitRenewal(opts: {
451	  server: DueServer;
452	  charge: RenewalCharge;
453	  newExpiry: Date;
454	}): Promise<"renewed" | "insufficient" | "already"> {
455	  const { server, charge, newExpiry } = opts;
456	  const renewCents = charge.totalCents;
457	  const { extraDiskCents, extraDiskMonthlyCents } = charge;
458	  const periodStart = server.expiresAt!;
459	
460	  try {
461	    await db.$transaction(async (tx) => {
462	      const advanced = await tx.server.updateMany({
463	        where: { id: server.id, expiresAt: server.expiresAt },
464	        data: {
465	          expiresAt: newExpiry,
466	          // The period is paid, so the collection state that belonged to it dies
467	          // with it. Leaving a stage behind would hand the NEXT period a
468	          // half-spent retry budget and the wrong dunning email.
469	          dunningStage: 0,
470	          dunningNextAt: null,
471	          dunningPayUrl: null,
472	        },
473	      });
474	      if (advanced.count === 0) throw new AlreadyRenewedError();
475	      await debitWallet(tx, server.userId, renewCents);
476	      await tx.walletTransaction.create({
477	        data: {
478	          userId: server.userId,
479	          amountCents: -renewCents,
480	          description: `Renewal: ${charge.label} (${server.hostname})`,
481	        },
482	      });
483	      // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
484	      // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
485	      // never producing a second invoice for the same period.
486	      await tx.invoice.create({
487	        data: invoiceCreateData({
488	          userId: server.userId,
489	          description: `Renewal: ${charge.label} (${server.hostname})`,
490	          status: "PAID",
491	          period: { start: periodStart, end: newExpiry },
492	          // Extra disk gets its OWN line so the customer sees exactly what the
493	          // permanent storage costs each cycle; the lines sum back to renewCents.
494	          lineItems: [
495	            {
496	              description: `${charge.label} — ${server.hostname}`,
497	              qty: 1,
498	              unitCents: renewCents - extraDiskCents,
499	              amountCents: renewCents - extraDiskCents,
500	            },
501	            ...(extraDiskCents > 0
502	              ? [
503	                  {
504	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthlyCents / 100).toFixed(2)}/mo)`,
505	                    qty: 1,
506	                    unitCents: extraDiskCents,
507	                    amountCents: extraDiskCents,
508	                  },
509	                ]
510	              : []),
511	          ],
512	        }),
513	      });
514	      await tx.auditLog.create({
515	        data: { userId: server.userId, action: "billing.renewed", detail: server.id },
516	      });
517	    });
518	  } catch (e) {
519	    if (e instanceof InsufficientBalanceError) {
520	      console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
521	      return "insufficient";
522	    }
523	    if (e instanceof AlreadyRenewedError) return "already"; // someone else advanced the period
524	    throw e;
525	  }
526	
527	  // The period is settled. Any 3-D Secure challenge still hanging off it is a
528	  // loaded gun: anything that later confirms that intent takes a SECOND payment
529	  // for a period we have already been paid for. Only worth a Stripe round-trip
530	  // when this server was actually mid-dunning.
531	  if (server.dunningStage > 0 || server.dunningPayUrl) {
532	    await cancelPendingChargeForMarker(
533	      server.user.stripeCustomerId,
534	      renewalChargeMarker(server.id, periodStart),
535	    );
536	  }
537	  return "renewed";
538	}
