850	/**
851	 * When this overdue server may be paused — null means never (auto-suspend is off).
852	 *
853	 * With a card in play the deadline is CARD_SUSPEND_DAY past expiry: one clear day
854	 * after the final-notice email, so the customer always gets a full day with the
855	 * warning in hand before anything stops. Without a card there is nothing to wait
856	 * for beyond the configured grace period.
857	 *
858	 * The deadline also never lands BEFORE an attempt we have promised. A worker that
859	 * was down for the first five days starts the sequence late; suspending on the
860	 * calendar alone would then pause a server minutes after emailing "we'll try your
861	 * card again on <date>" — the exact broken promise this whole feature exists to
862	 * stop. That slip is capped (see SUSPEND_SLIP_CAP_DAYS) and only applies while
863	 * attempts actually remain, so a permanently failing Stripe cannot defer
864	 * suspension forever.
865	 */
866	function suspendDueAt(
867	  server: { expiresAt: Date | null; dunningStage: number; dunningNextAt: Date | null },
868	  hasCard: boolean,
869	  cfg: DunningConfig,
870	): Date | null {
871	  if (!cfg.autoSuspend || !server.expiresAt) return null;
872	  const days = hasCard ? Math.max(cfg.graceDays, CARD_SUSPEND_DAY) : cfg.graceDays;
873	  const at = new Date(server.expiresAt.getTime() + days * DAY);
874	  if (!hasCard || server.dunningStage >= DUNNING_EXHAUSTED || !server.dunningNextAt) return at;
875	  if (server.dunningNextAt <= at) return at;
876	  const cap = new Date(server.expiresAt.getTime() + (days + SUSPEND_SLIP_CAP_DAYS) * DAY);
877	  return server.dunningNextAt < cap ? server.dunningNextAt : cap;
878	}
