 * The deadline also never lands BEFORE an attempt we have promised. A worker that
 * was down for the first five days starts the sequence late; suspending on the
 * calendar alone would then pause a server minutes after emailing "we'll try your
 * card again on <date>" — the exact broken promise this whole feature exists to
 * stop. That slip is capped (see SUSPEND_SLIP_CAP_DAYS) and only applies while
 * attempts actually remain, so a permanently failing Stripe cannot defer
 * suspension forever.
 */
function suspendDueAt(
  server: { expiresAt: Date | null; dunningStage: number; dunningNextAt: Date | null },
  hasCard: boolean,
  cfg: DunningConfig,
): Date | null {
  if (!cfg.autoSuspend || !server.expiresAt) return null;
  const days = hasCard ? Math.max(cfg.graceDays, CARD_SUSPEND_DAY) : cfg.graceDays;
  const at = new Date(server.expiresAt.getTime() + days * DAY);
  if (!hasCard || server.dunningStage >= DUNNING_EXHAUSTED || !server.dunningNextAt) return at;
  if (server.dunningNextAt <= at) return at;
  const cap = new Date(server.expiresAt.getTime() + (days + SUSPEND_SLIP_CAP_DAYS) * DAY);
  return server.dunningNextAt < cap ? server.dunningNextAt : cap;
}

