 * The deadline also never lands BEFORE a date we have promised the customer. A
 * worker that was down for the first five days starts the sequence late, and
 * suspending on the calendar alone would then pause a server minutes after emailing
 * "we'll try your card again on <date>" or "this is your final notice" — the exact
 * broken promise this whole feature exists to stop. `dunningNextAt` carries that
 * promise (the next attempt while any remain, the clear day once they are spent),
 * and the slip it can buy is capped by SUSPEND_SLIP_CAP_DAYS so a permanently
 * failing Stripe cannot defer suspension forever.
 */
function suspendDueAt(
  server: { expiresAt: Date | null; dunningStage: number; dunningNextAt: Date | null },
  hasCard: boolean,
  cfg: DunningConfig,
): Date | null {
  if (!cfg.autoSuspend || !server.expiresAt) return null;
  const days = calendarSuspendDay(cfg, hasCard);
  const at = new Date(server.expiresAt.getTime() + days * DAY);
  if (!hasCard || !server.dunningNextAt || server.dunningNextAt <= at) return at;
  const cap = new Date(server.expiresAt.getTime() + (days + SUSPEND_SLIP_CAP_DAYS) * DAY);
  return server.dunningNextAt < cap ? server.dunningNextAt : cap;
}

/**
 * Days past expiry of the plain calendar deadline, before any late-sequence slip.
 * One expression, because `suspendDueAt` and the exhausted-sequence bookkeeping in
 * `recordDeclinedAttempt` must agree on it exactly or a server can be scheduled to
 * pause on a day the suspension check does not recognise.
 */
function calendarSuspendDay(cfg: DunningConfig, hasCard: boolean): number {
  return hasCard ? Math.max(cfg.graceDays, CARD_SUSPEND_DAY) : cfg.graceDays;
}

