843	/**
844	 * When the Nth failed attempt should be followed by another one.
845	 *
846	 * Floored at MIN_RETRY_GAP_MS so a worker that has been down for a week does not
847	 * discover four overdue slots at once and fire the entire sequence — three charges
848	 * and three emails — inside a single afternoon.
849	 */
850	function nextRetryAt(expiresAt: Date, failures: number, now: Date): Date | null {
851	  if (failures >= DUNNING_EXHAUSTED) return null;
852	  const scheduled = new Date(expiresAt.getTime() + retryDayFor(failures) * DAY);
853	  const floor = new Date(now.getTime() + MIN_RETRY_GAP_MS);
854	  return scheduled > floor ? scheduled : floor;
855	}
